window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q13"]=window.__LIBQ["the-gioi-hoan-my"]["q13"]||{};window.__LIBQ["the-gioi-hoan-my"]["q13"]["map"]={"updatedAt":"2026-07-26","count":170,"nodes":[{"id":"phan-ngu-hanh-chi-dia","name":"Phản Ngũ Hành chi địa","cn":"","capDo":"khac","parentId":"ngu-hanh-dai-luc","blurb":"Khu vực nằm tại âm dương mắt đối xứng với vị trí chuẩn Thế Giới thụ cắm rễ. Nơi đây được cho là chỗ phong ấn Ngũ ma phong thiên loại.","detail":"Phản Ngũ Hành chi địa thuộc cấu trúc Âm Dương đồ của Phản Ngũ Hành đại trận. Đây là khu vực cực kỳ nguy hiểm vì những người từng tiến vào tìm kiếm đều chết, khiến Nhị trưởng lão chỉ quyết định đến quan sát từ xa.","theLucLienQuan":["Thiên Thần thư viện"],"nguon":["@c1201"]},{"id":"am-duong-nhan","name":"Âm Dương nhãn","cn":"","capDo":"khac","parentId":"ngu-hanh-dai-luc","blurb":"Khu vực nằm trong vùng núi có Ngũ Hành bản nguyên khí nồng đậm, được các trưởng lão xác định là mục tiêu của chuyến đi.","detail":"Âm Dương nhãn là trung tâm của khu vực phong ấn, Phản Ngũ Hành đại trận và dấu tích luyện đại dược. Đường vào nơi này dẫn tới một thung lũng phủ sương mù, chứa nhiều hài cốt cùng văn khắc cổ.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1202"]},{"id":"thung-lung-phan-ngu-hanh","name":"Thung lũng phản Ngũ Hành","cn":"","capDo":"khac","parentId":"am-duong-nhan","blurb":"Thung lũng phủ sương mù tại Âm Dương nhãn, nơi Phản Ngũ Hành đại trận từng vận chuyển và nhiều cường giả đã bỏ mạng hoặc tọa hóa.","detail":"Trong cốc có hài cốt của nhiều chủng tộc, kể cả Chí Tôn, cùng các văn khắc kể về việc phong ấn cự hung và luyện đại dược. Đại trận tại đây đã ngừng vận chuyển, cho phép hai viện tiến vào nếu không xúc động phần phong ấn còn lại.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1202"]},{"id":"an-giau-co-dia","name":"Ẩn giấu cổ địa","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian chân thực nằm phía sau lớp thạch bích trận pháp. Nơi đây có nhiều thần dược quý hiếm nhưng cũng tồn tại phù văn bảo vệ nguy hiểm.","detail":"Cổ địa có mặt đất đỏ sẫm như từng trải qua một trận chiến đẫm máu, ánh sáng tối tăm và nhiều khu vực không có cây cỏ. Bên trong vẫn ẩn chứa thiên địa linh túy, Dẫn hồn liên, Phượng Hoàng thảo cùng các phù văn có thể chém bị thương người hái thuốc.","theLucLienQuan":["Tiên viện","Thiên Thần thư viện"],"nguon":["@c1203"]},{"id":"hem-nui-che-giau-co-dia","name":"Hẻm núi che giấu cổ địa","cn":"","capDo":"khac","parentId":null,"blurb":"Hẻm núi bề ngoài kết thúc tại một vách đá nhưng thực chất chỉ là lớp che giấu cổ địa. Thạch bích nơi đây là một trận pháp sàng lọc người tiến vào.","detail":"Các trưởng lão hai viện dựa vào tọa độ của chuẩn Thế Giới thụ và Âm Dương nhãn để nhận ra hẻm núi chỉ là biểu tượng bên ngoài. Vách đá cuối hẻm núi ngăn người mạnh xâm nhập nhưng cho những đệ tử trẻ có sức mạnh phù hợp xuyên qua.","theLucLienQuan":["Tiên viện","Thiên Thần thư viện"],"nguon":["@c1203"]},{"id":"ao-dan-hon-lien","name":"Ao Dẫn hồn liên","cn":"","capDo":"khac","parentId":"an-giau-co-dia","blurb":"Một ao thần dịch trong Ẩn giấu cổ địa, nơi Dẫn hồn liên sắp trưởng thành. Khu vực này trở thành trung tâm cuộc hỗn chiến giữa các cường giả trẻ tuổi.","detail":"Ao nằm gần vị trí Thạch Hạo vừa tiến vào cổ địa và chứa một cây sen trắng Dẫn hồn liên. Giá trị hồi sinh nguyên thần của thần dược khiến Thạch Hạo, Lục Đà, Vương Hi cùng nhiều cao thủ Tiên viện lao vào tranh đoạt.","theLucLienQuan":["Tiên viện","Thiên Thần thư viện"],"nguon":["@c1203"]},{"id":"than-tri-cua-dan-hon-lien","name":"Thần trì của Dẫn Hồn Liên","cn":"","capDo":"khac","parentId":"ao-dan-hon-lien","blurb":"Thần trì rộng vài trượng, chứa thần dịch óng ánh cùng Tiên Thiên tinh khí. Đây là nơi Dẫn Hồn Liên cắm rễ và là trung tâm cuộc hỗn chiến giữa các chí tôn trẻ tuổi.","detail":"Dẫn Hồn Liên mọc giữa thần trì, khiến khu vực này bị học sinh Thiên Thần Thư Viện và đệ tử Tiên Viện phong tỏa. Bất kỳ ai tiến vào hái thuốc đều phải đối mặt với đòn hợp kích của những người đang tranh đoạt.","theLucLienQuan":["Tiên Viện","Thiên Thần Thư Viện"],"nguon":["@c1204"]},{"id":"co-dia-toi-tam","name":"Cổ địa tối tăm","cn":"","capDo":"khac","parentId":null,"blurb":"Một cổ địa rộng lớn, thiếu ánh sáng nhưng ẩn chứa nhiều thần dược, thánh dược và linh thảo.","detail":"Người tiến vào cổ địa xuất hiện tại những vị trí khác nhau. Nơi này đã xuất hiện hơn sáu loại thần dược, còn lối ra xuyên qua vách đá dẫn về khu vực có trưởng lão của Thiên Thần Thư Viện và Tiên Viện.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1206"]},{"id":"khu-vuc-nghiet-long-duoc","name":"Khu vực Nghiệt Long dược","cn":"","capDo":"khac","parentId":"co-dia-toi-tam","blurb":"Khu vực diễn ra cuộc hỗn chiến tranh đoạt Nghiệt Long dược.","detail":"Nghiệt Long dược bị trận pháp cầm cố tại đây. Thập Quan Vương, Vương Hi, Lục Đà cùng nhiều chí tôn trẻ tuổi tham gia tranh đoạt, trước khi Thập Quan Vương phá vòng vây và bắt được thần dược.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1206"]},{"id":"khu-vuc-bat-tran-ky","name":"Khu vực Bát trân kỳ","cn":"","capDo":"khac","parentId":"co-dia-toi-tam","blurb":"Vùng đất nơi Bát trân kỳ xuất hiện và gây ra một cuộc hỗn chiến.","detail":"Các cường giả dùng bí pháp phong tỏa đại địa để ngăn Bát trân kỳ độn thổ. Thạch Hạo và Lục Đà giao phong trực diện tại khu vực này, khiến gan bàn tay Lục Đà bị đánh nứt.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1206"]},{"id":"vuon-thuoc-bi-vut-bo","name":"Vườn thuốc bị vứt bỏ","cn":"","capDo":"khac","parentId":null,"blurb":"Một dược viên hoang phế có nhiều thần dược sinh trưởng.","detail":"Thạch Hạo nhận định khu vực này là một vườn thuốc đã bị vứt bỏ. Nơi đây có nhiều thần dược và là khu vực bát trân kỳ xuất hiện.","theLucLienQuan":[],"nguon":["@c1207"]},{"id":"ngon-nui-thap-phat-ra-te-linh-van","name":"Ngọn núi thấp phát ra tế linh văn","cn":"","capDo":"khac","parentId":"vuon-thuoc-bi-vut-bo","blurb":"Ngọn núi trọc cao không quá trăm mét, là nguồn phát ra tế linh văn nguyên thủy.","detail":"Ngọn núi thấp có một tiểu miếu đổ nát dưới chân và vách đá mang các đồ án cổ. Tế linh văn từ trong núi chiếu sáng bầu trời, thu hút những người đang tranh đoạt linh dược tới thăm dò.","theLucLienQuan":["Tiên Viện"],"nguon":["@c1207"]},{"id":"tieu-mieu-do-nat-duoi-chan-nui","name":"Tiểu miếu đổ nát dưới chân núi","cn":"","capDo":"khac","parentId":"ngon-nui-thap-phat-ra-te-linh-van","blurb":"Một ngôi miếu nhỏ hư hỏng nặng nằm trước ngọn núi phát ra tế linh văn.","detail":"Tiểu miếu chỉ có một gian và đã đổ nát. Công trình nằm ngay dưới chân ngọn núi thấp chứa vách đá cùng những đồ án cổ.","theLucLienQuan":[],"nguon":["@c1207"]},{"id":"canh-cua-khac-tren-vach-da","name":"Cánh cửa khắc trên vách đá","cn":"","capDo":"khac","parentId":"ngon-nui-thap-phat-ra-te-linh-van","blurb":"Hình khắc cánh cửa trên vách đá dần hiện rõ dưới những đợt công kích và có một sinh vật hung bạo tồn tại phía sau.","detail":"Hình cánh cửa ban đầu rất mơ hồ nhưng trở nên rõ ràng hơn khi Trích Tiên, Độc Cô Vân và các cường giả Tiên Viện công kích đồ án. Sau khi nhận máu vàng của Độc Cô Vân, từ phía sau cửa vang lên tiếng gào và một bàn tay đầy lông xuyên ra ngoài.","theLucLienQuan":["Tiên Viện"],"nguon":["@c1207"]},{"id":"duong-nui-da-ngu-ma-phong-thien-chung","name":"Đường núi đá Ngũ Ma Phong Thiên Chủng","cn":"","capDo":"khac","parentId":"ngon-nui-thap-phat-ra-te-linh-van","blurb":"Con đường núi đá được nhắc trong phần tế linh văn mà Thanh Y giải đọc.","detail":"Nội dung Thanh Y nhận biết cho biết muốn tới Ngũ Ma Phong Thiên Chủng thì phải đi theo đường núi đá này. Bản chất và điểm đến cụ thể của con đường chưa được làm rõ.","theLucLienQuan":[],"nguon":["@c1207"]},{"id":"nguyen-quan-cua-nguoi-bao-ve-mot-mach","name":"Nguyên quán của người bảo vệ một mạch","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi nghỉ chân và nguyên quán mà Độc Cô Vân đang tìm cổ lộ để đi tới.","detail":"Thanh Y nghe hiểu một phần cuộc đối thoại và xác định Độc Cô Vân đang hỏi đường tới nguyên quán của bộ tộc mình. Địa điểm cụ thể chưa được nêu, nhưng những người có mặt cho rằng nơi này dường như không thuộc Cửu Thiên Thập Địa.","theLucLienQuan":["Người bảo vệ một mạch"],"nguon":["@c1208"]},{"id":"co-huong-cua-thu-ho-gia","name":"Cố hương của Thủ Hộ giả","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tịnh thổ tổ tiên của những sinh linh mang dòng máu vàng thần thánh. Người đã rời nơi này và nhiễm hồng trần khí không thể quay về.","detail":"Cố hương nằm ở cuối một cổ lộ mà Độc Cô Vân muốn truy tìm. Việc mở giới môn dẫn tới nơi đây có thể triệu gọi những cường giả đáng sợ khiến cả dị vực phải kiêng kỵ.","theLucLienQuan":["Người bảo vệ một mạch"],"nguon":["@c1209"]},{"id":"co-lo-dan-toi-co-huong-thu-ho-gia","name":"Cổ lộ dẫn tới cố hương Thủ Hộ giả","cn":"","capDo":"khac","parentId":"co-huong-cua-thu-ho-gia","blurb":"Con đường dẫn tới tịnh thổ tổ tiên mà Độc Cô Vân quyết tâm tìm kiếm. Hoàng tộc dị vực từng hứa giao con đường này cho hậu nhân Thủ Hộ giả.","detail":"Sinh linh lông đỏ từ chối tiết lộ vị trí cổ lộ vì lo việc mở giới môn ở cuối đường sẽ dẫn tới hậu quả ngoài ý muốn và triệu gọi những cường giả đáng sợ.","theLucLienQuan":["Người bảo vệ một mạch","Hoàng tộc cổ xưa dị vực"],"nguon":["@c1209"]},{"id":"ngu-ma-phong","name":"Ngũ Ma phong","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực gắn với truyền thuyết Ngũ Ma phong thiên loại. Thạch Hạo nhận ra viên đạo chủng được Mạc Đạo nhắc tới có thể chính là thiên loại trong truyền thuyết này.","detail":"Nơi đây còn có các lò luyện đan được Thanh Y suy đoán đang phong ấn nhiều thành viên của một hoàng tộc dị vực, trong đó có thể có trưởng bối và cường giả mạnh hơn sinh linh lông đỏ vừa thoát vây.","theLucLienQuan":["Hoàng tộc cổ xưa dị vực"],"nguon":["@c1209"]},{"id":"co-gioi-mon","name":"Cổ giới môn","cn":"","capDo":"khac","parentId":null,"blurb":"Giới môn mà Độc Cô Vân muốn vượt qua để trở về tổ địa của bộ tộc.","detail":"Sinh vật lông đỏ nắm manh mối về cổ lộ dẫn tới cổ giới môn và dùng thông tin này làm điều kiện buộc Độc Cô Vân giúp giải thoát tổ tiên của nó.","theLucLienQuan":["Bộ tộc hậu nhân người bảo vệ","Hoàng tộc dị vực của sinh vật lông đỏ"],"nguon":["@c1210"]},{"id":"the-gioi-sau-vach-da","name":"Thế giới sau vách đá","cn":"","capDo":"gioi-nho","parentId":"canh-cua-khac-tren-vach-da","blurb":"Không gian nằm phía sau cánh cửa và những hình chạm khắc trên vách núi.","detail":"Nơi này được cho là chứa bảo bình cùng một viên thiên loại có thể tác động đến phong ấn của các cao thủ thuộc bộ tộc sinh vật lông đỏ.","theLucLienQuan":["Hoàng tộc dị vực của sinh vật lông đỏ"],"nguon":["@c1210"]},{"id":"thanh-ha-mau-vang","name":"Thánh hà màu vàng","cn":"","capDo":"khac","parentId":null,"blurb":"Dòng sông tại tổ địa của bộ tộc hậu nhân người bảo vệ.","detail":"Độc Cô Vân muốn tắm trong dòng Thánh hà này để kim huyết sôi trào, thân thể lột xác và hoàn thành nghi thức niết bàn của bộ tộc.","theLucLienQuan":["Bộ tộc hậu nhân người bảo vệ"],"nguon":["@c1210"]},{"id":"thach-bich-chien-truong","name":"Thạch bích chiến trường","cn":"","capDo":"khac","parentId":null,"blurb":"Vách đá nơi sinh linh lông đỏ chạy vào sau khi bị Thạch Hạo đánh trọng thương.","detail":"Sinh linh lông đỏ lùi vào thạch bích để thoát khỏi truy sát. Độc Cô Vân và Thạch Hạo tiến vào trước, sau đó Thập Quan Vương, Trích Tiên cùng nhiều tu sĩ khác lần lượt xông theo.","theLucLienQuan":["Thiên Thần thư viện","Hoàng tộc dị vực"],"nguon":["@c1211"]},{"id":"vung-nui-phong-an-hoang-toc-di-vuc","name":"Vùng núi phong ấn Hoàng tộc dị vực","cn":"","capDo":"vuc","parentId":"the-gioi-sau-vach-da","blurb":"Quần sơn phủ sương mù nằm ở cuối bình nguyên, bao quanh Đại Đạo Bảo Bình.","detail":"Mỗi ngọn núi là một bộ phận của cơ cấu phong ấn. Khi kim huyết của Độc Cô Vân rơi xuống, các đỉnh núi mọc ra cây lớn có hoa chứa sinh linh dị vực mang vũ khí.","theLucLienQuan":["Hoàng tộc dị vực của sinh vật lông đỏ"],"nguon":["@c1212"]},{"id":"dai-dao-bao-binh-trung-tam-quan-son","name":"Đại Đạo Bảo Bình trung tâm quần sơn","cn":"","capDo":"khac","parentId":"vung-nui-phong-an-hoang-toc-di-vuc","blurb":"Khu vực trung tâm quần sơn, nơi đặt bảo bình đá lớn như núi dùng để giam giữ sinh linh dị vực.","detail":"Sinh linh lông đỏ chạy tới đây chữa thương, còn Độc Cô Vân xuyên không gian vào trong để tìm đáp án và dùng kim huyết kích hoạt cơ cấu phong ấn.","theLucLienQuan":["Hoàng tộc dị vực của sinh vật lông đỏ"],"nguon":["@c1212"]},{"id":"gioi-phan","name":"Giới Phần","cn":"","capDo":"vuc","parentId":null,"blurb":"Nơi đoàn người từng đi chiến thuyền và gặp một cường giả vô thượng hiện ra đe dọa.","detail":"Địa danh được nhắc lại khi mọi người suy đoán cường giả vô thượng từng xuất hiện tại đó có thể là cao thủ Hoàng tộc dị vực.","theLucLienQuan":["Hoàng tộc dị vực của sinh vật lông đỏ"],"nguon":["@c1212"]},{"id":"co-dia-quan-son","name":"Cổ địa quần sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng quần sơn lưu giữ dấu ấn chân thực của đại chiến Tiên cổ và ẩn giấu phần rễ còn lại của Mẫu Sào dị vực.","detail":"Dấu ấn lịch sử tại đây có thể mở thành cạm bẫy thời gian Luân Hồi, kéo người sống vào cuộc đại chiến cổ xưa. Bên dưới các ngọn núi là Mẫu Căn Hành khổng lồ nối liền toàn vùng.","theLucLienQuan":["Dị vực"],"nguon":["@c1213"]},{"id":"khu-co-dia-duoi-phan-ngu-hanh-dai-tran","name":"Khu cổ địa dưới phản Ngũ Hành đại trận","cn":"","capDo":"khac","parentId":"dai-luc-ngu-hanh","blurb":"Khu cổ địa được Phản Ngũ Hành đại trận bảo vệ, nơi đặt Đại Đạo Bảo Bình và bồi dưỡng thiên loại.","detail":"Đoàn hai viện rút khỏi khu vực sau khi dấu ấn hình người trở vào bình và sinh linh lông đỏ biến mất trong huyết quang.","theLucLienQuan":["Tiên Viện","Thiên Thần Thư Viện"],"nguon":["@c1214"]},{"id":"dai-luc-ngu-hanh","name":"Đại lục Ngũ hành","cn":"","capDo":"khac","parentId":null,"blurb":"Đại lục có Ngũ hành tinh khí nồng đậm, chứa nhiều đạo chủng, thần dược và vật liệu mang thuộc tính Ngũ hành.","detail":"Thạch Hạo và Thanh Y thám hiểm nhiều khu vực tại đây, thu đủ năm loại đạo chủng kim, mộc, thủy, hỏa, thổ. Chuẩn Thế Giới Thụ hoàng kim cũng hấp thu tinh khí của đại lục để tiến hóa.","theLucLienQuan":["Tiên Viện","Thiên Thần Thư Viện"],"nguon":["@c1214"]},{"id":"vung-phap-tac","name":"Vùng pháp tắc","cn":"","capDo":"khac","parentId":null,"blurb":"Một thánh thổ do quy tắc thế giới xây dựng thay vì vùng đất chân thực. Nơi đây có tường vân, đại đạo phù văn và các hạt giống do đạo tắc biến thành.","detail":"Chuẩn Thế Giới Thụ dẫn đoàn hai viện tới vùng này. Sau hơn hai mươi ngày tìm kiếm, họ phát hiện Huyền Không đảo cùng cây thần bí mang hàng nghìn trái đại đạo.","theLucLienQuan":["Tiên Viện","Thiên Thần Thư Viện"],"nguon":["@c1214"]},{"id":"huyen-khong-dao-cuc-tay","name":"Huyền Không đảo cực tây","cn":"","capDo":"khac","parentId":"vung-phap-tac","blurb":"Hòn đảo treo trên các quy tắc ở cực tây vùng pháp tắc, bao quanh bởi lôi đình, thái âm khí và Thái Dương tinh hỏa.","detail":"Quy tắc thiên địa bài xích khiến đoàn người không thể đặt chân lên đảo. Trong khe nứt hư không tại đây có cây nghi là Vạn Đạo Thụ và một cổ nhân bị xích.","theLucLienQuan":["Tiên Viện","Thiên Thần Thư Viện"],"nguon":["@c1214"]},{"id":"khe-nut-hu-khong-tren-huyen-khong-dao","name":"Khe nứt hư không lớn trên Huyền Không đảo","cn":"","capDo":"khac","parentId":"huyen-khong-dao-cuc-tay","blurb":"Vết nứt hư không nơi cây thần bí mang hàng nghìn trái và cổ nhân bị xích lúc ẩn lúc hiện.","detail":"Cây thần bí dường như không được quy tắc thiên địa dung nạp. Gần cây có một cổ nhân ngồi xếp bằng, bị xích sắt rỉ xuyên qua xương vai.","theLucLienQuan":[],"nguon":["@c1214"]},{"id":"huyen-khong-dao","name":"Huyền Không đảo","cn":"","capDo":"khac","parentId":"gioi-phan","blurb":"Hòn đảo trong Giới Phần nơi Vạn Đạo Thụ cắm rễ giữa khe nứt hư không.","detail":"Huyền Không đảo được bao quanh bởi nhiều Lôi Trì, xích thần trật tự Thái Âm và Thái Dương. Một sinh linh bị xích canh giữ Vạn Đạo Thụ tại đây, còn bên trong đảo có thi hài của những tồn tại cực mạnh từng chết vì tranh đoạt cây.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1215"]},{"id":"chien-truong-co-day-thi-hai","name":"Chiến trường cổ đầy thi hài","cn":"","capDo":"khac","parentId":"gioi-phan","blurb":"Chiến trường rộng lớn trong Giới Phần, chứa sao vỡ, thi thể khổng lồ và cổ huyết.","detail":"Tinh huyết bất diệt của Tiên Thiên Thần Ma tử trận tại đây đã thông linh và hóa thành Huyết Chủng. Máu bạc cùng thi khí trong khu vực có thể làm tan chảy pháp khí, khiến tu sĩ mục nát hoặc hóa thành bùn nhão.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1215"]},{"id":"quan-the-kien-truc-co-trong-gioi-phan","name":"Quần thể kiến trúc cổ trong Giới Phần","cn":"","capDo":"khac","parentId":"gioi-phan","blurb":"Cụm kiến trúc cổ trôi nổi chứa nhiều bóng hình và linh hồn đạo chủng.","detail":"Tàn hồn của các cường giả cổ đại tại đây đã thông linh và hóa thành anh linh hạt giống. Những đạo chủng này có thể phản phệ người tìm cách thu lấy.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1215"]},{"id":"tien-tich","name":"Tiên tích","cn":"","capDo":"khac","parentId":null,"blurb":"Những động phủ và di tích còn sót lại từ thời Tiên cổ.","detail":"Tiên Viện đã khai quật nhiều Tiên tích sau đại chiến Tiên cổ. Các địa điểm này được Nhị Trường Lão suy đoán là nguồn của những vô thượng cổ loại mà Tiên Viện có thể đang cất giữ.","theLucLienQuan":["Tiên Viện"],"nguon":["@c1216"]},{"id":"dong-phu-tien-gia-ky-nguyen-truoc","name":"Động phủ tiên gia kỷ nguyên trước","cn":"","capDo":"khac","parentId":null,"blurb":"Di tích tiên gia từ kỷ nguyên trước, nơi Tiên Viện đào được nhiều cực mạnh cổ chủng.","detail":"Những cổ chủng được tìm thấy tại đây từng vỡ nát và bị thương nặng cùng chủ nhân trong đại chiến Tiên cổ, sau đó đoàn tụ nhưng vẫn cần bảo huyết chữa trị.","theLucLienQuan":["Tiên Viện"],"nguon":["@c1217"]},{"id":"kim-quang-dai-dao","name":"Kim quang đại đạo","cn":"","capDo":"khac","parentId":null,"blurb":"Con đường nơi nhóm người Tiên Viện bị đánh bay đứng lên ngăn cản Thạch Hạo.","detail":"Một số người Tiên Viện đứng trên Kim quang đại đạo, quát Thạch Hạo và cầm pháp khí định ngăn hắn tiếp tục trấn áp hai đệ tử.","theLucLienQuan":["Tiên Viện"],"nguon":["@c1219"]},{"id":"cau-vong-bay-mau","name":"Cầu vồng bảy màu","cn":"","capDo":"khac","parentId":null,"blurb":"Lối đi được phóng ra từ cánh cửa trên tinh cầu đá của Tiên Viện.","detail":"Cầu vồng bảy màu nối từ tinh cầu đá ra bên ngoài, đưa các thiên tài Tiên Viện cùng Tiểu Thiên Vương xuất hiện trước đám đông.","theLucLienQuan":["Tiên Viện"],"nguon":["@c1219"]},{"id":"than-cap-vo-dai","name":"Thần Cấp võ đài","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Võ đài cấp Thần được Thạch Hạo chọn làm nơi giao chiến công bằng với Tiểu Thiên Vương.","detail":"Sau khi từ chối hai phương thức văn đấu, Thạch Hạo đề nghị cùng Tiểu Thiên Vương lên võ đài này tiến hành một trận chiến thực sự để phân định tranh chấp.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện"],"nguon":["@c1220"]},{"id":"than-cap-vo-dai-tren-khong-trung","name":"Thần Cấp võ đài trên không trung","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Võ đài khổng lồ phủ tiên vụ được đưa tới giữa không trung tại Thiên Thần Thư Viện. Đây là chiến trường chính thức để các viện tranh ngôi Thiên Thần cảnh đệ nhất nhân.","detail":"Các lão quái vật đưa võ đài tới sau khi tranh chấp giữa Tiên Viện và Thánh Viện bùng lên. Thạch Hạo bị chuyển thẳng lên võ đài làm đài chủ, còn cốt văn hiện ra để xác nhận mục tiêu của cuộc chiến.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện","Thánh Viện"],"nguon":["@c1221"]},{"id":"vo-dai-co-cua-thien-than-thu-vien","name":"Võ đài cổ của Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Chiến trường cổ trôi nổi rộng như một khối lục địa, được dùng cho cuộc tranh ngôi đệ nhất Thiên Thần cảnh.","detail":"Nền đá của võ đài phủ đại đạo phù văn và từng được đại năng cổ đại tế luyện, nhờ đó có thể chịu được cuộc giao chiến toàn lực giữa những cao thủ Thiên Thần cảnh.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện","Thánh Viện"],"nguon":["@c1222"]},{"id":"tien-tho-tim-co-hoi-niet-ban","name":"Tiên thổ tìm cơ hội niết bàn","cn":"","capDo":"khac","parentId":null,"blurb":"Tiên thổ nơi nhóm tu sĩ theo con đường kiếp này pháp tới tìm kiếm cơ hội niết bàn.","detail":"Nhóm Tào Vũ Sinh, Thái Âm Ngọc Thỏ và những tu sĩ ba ngàn châu từng tới nơi này thay vì Giới Phần, sau đó trở về Thiên Thần Thư Viện trên chiến hạm.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1222"]},{"id":"vo-dai","name":"Võ đài","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Thạch Hạo và Vũ Vô Địch giao chiến hơn ba nghìn hiệp.","detail":"Võ đài có phù văn bảo hộ giúp làm suy yếu sóng âm, nhưng vẫn rung chuyển dữ dội trước Ngao hống và cuộc giao chiến kéo dài giữa hai người.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện","Thánh Viện"],"nguon":["@c1224"]},{"id":"tinh-cau-da","name":"Tinh cầu đá","cn":"","capDo":"khac","parentId":null,"blurb":"Tinh cầu bằng đá mà Vũ Vô Địch trở vào sau khi thất bại trước Thạch Hạo.","detail":"Vũ Vô Địch điều khiển một chiếc thuyền con rời võ đài và tiến vào tinh cầu đá này.","theLucLienQuan":["Tiên Viện"],"nguon":["@c1225"]},{"id":"loi-dai-thien-than-thu-vien","name":"Lôi đài Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Lôi đài nơi Thạch Hạo hoàn tất chiến thắng trước những cao thủ cùng cảnh của Tiên Viện và Thánh Viện.","detail":"Sau thất bại của năm cao thủ Thánh Viện và Vũ Vô Địch, không còn tu sĩ Thiên Thần cảnh nào dám tiếp tục lên đài đối đầu Thạch Hạo.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện","Thánh Viện"],"nguon":["@c1226"]},{"id":"vo-thuong-tien-tho-chua-xac-dinh","name":"Vô thượng Tiên thổ chưa xác định","cn":"","capDo":"khac","parentId":null,"blurb":"Tiên thổ chưa xác định mà động phủ của Tiên viện, Thánh viện và Thiên Thần thư viện có thể cùng được dời tới.","detail":"Khả năng ba viện hội tụ tại đây khiến những đệ tử vừa chọn các con đường khác nhau vẫn có cơ hội gặp lại trong tương lai gần.","theLucLienQuan":["Tiên viện","Thánh viện","Thiên Thần thư viện"],"nguon":["@c1227"]},{"id":"tu-truc-lam","name":"Tử trúc lâm","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Rừng trúc tím yên tĩnh trong Thiên Thần Thư Viện, nơi Thạch Hạo suy xét con đường tu hành.","detail":"Khu rừng có đường lát đá cuội và dòng suối chảy qua rễ trúc. Thạch Hạo kiểm tra kinh thư, kiếm thai, Nguyên Thủy Chân Giải và hạt giống kỳ dị tại đây trước khi quyết định tìm Đại trưởng lão.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1228"]},{"id":"dam-lay-noi-dai-truong-lao-cu-tru","name":"Đầm lầy nơi Đại trưởng lão cư trú","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Khu vực có nhà tranh, ao bùn và đá lớn, là nơi Đại trưởng lão cư trú và thả câu.","detail":"Vùng đầm lầy thông với động phủ dưới lòng đất. Đại trưởng lão dùng thánh dược làm mồi để câu một sinh linh giảo hoạt trong động phủ, nhưng nhiều năm vẫn chưa bắt được.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1228"]},{"id":"tien-gia-dong-phu-duoi-thien-than-thu-vien","name":"Tiên gia động phủ dưới Thiên Thần Thư Viện","cn":"","capDo":"gioi-nho","parentId":"thien-than-thu-vien-dia-diem","blurb":"Tòa động phủ chưa được mở ra nằm dưới khu di tích của Thiên Thần Thư Viện.","detail":"Động phủ có thể thông với vùng đầm lầy nơi Đại trưởng lão cư trú. Bên trong có một sinh linh giảo hoạt mà ông đã thả câu nhiều năm nhưng chưa bắt được; chưa thể xác định nơi này có chứa vô thượng hạt giống hay không.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1228"]},{"id":"dong-phu-tien-gia-co-dai","name":"Động phủ tiên gia cổ đại","cn":"","capDo":"khac","parentId":null,"blurb":"Những động phủ cổ từng được Đại trưởng lão khai quật để tìm bí sách và tài nguyên.","detail":"Các bí sách và tài nguyên thu được từ nhiều động phủ tiên gia cổ đại đã góp phần tạo nên nền tảng nghiên cứu lấy thân làm chủng và sự tích lũy của Thiên Thần thư viện.","theLucLienQuan":["Thiên Thần thư viện"],"nguon":["@c1229"]},{"id":"ky-di-co-dia-chua-tru-ta-than-truc-va-hoang-tuyen-qua","name":"Kỳ dị cổ địa chứa trừ tà thần trúc và hoàng tuyền quả","cn":"","capDo":"khac","parentId":null,"blurb":"Cổ địa đặc biệt đồng thời có trừ tà thần trúc và hoàng tuyền quả.","detail":"Thạch Hạo phải tự đến cổ địa này để tìm hai thần vật còn thiếu. Nơi đây cũng được Đại trưởng lão chọn làm điểm khởi đầu để hắn luyện thân, rèn nguyên thần và chuẩn bị cho lần đột phá lấy thân làm chủng.","theLucLienQuan":["Thiên Thần thư viện"],"nguon":["@c1229"]},{"id":"tien-khau","name":"Tiên Khâu","cn":"","capDo":"khac","parentId":"vo-luong-thien","blurb":"Ngọn núi cao mười vạn trượng ẩn trong hư không, chỉ người mang ngọc bài đặc biệt mới có thể nhìn thấy và tiếp cận.","detail":"Tiên Khâu có sơn đạo hơn chín vạn chín nghìn bậc và tạo ra áp lực như vô số tinh thần đè xuống. Thạch Hạo mất nửa tháng leo tới đỉnh, trong quá trình đó nhiều đoạn xương của hắn bị nứt.","theLucLienQuan":["Thiên Thần thư viện"],"nguon":["@c1230","@c1232"]},{"id":"huyen-khong-tu","name":"Huyền Không Tự","cn":"","capDo":"khac","parentId":"tien-khau","blurb":"Ngôi chùa cổ bằng gạch đá vàng huyền trên đỉnh Tiên Khâu.","detail":"Huyền Không Tự hiện ra giữa ánh bình minh cùng tiếng đại chung. Trước chùa có nhiều sinh linh mang ánh mắt tang thương, khí tức đáng sợ và binh khí cực mạnh đang ngồi ngộ đạo.","theLucLienQuan":[],"nguon":["@c1230"]},{"id":"dai-hoang-gan-tien-khau","name":"Đại Hoang gần Tiên Khâu","cn":"","capDo":"vuc","parentId":"vo-luong-thien","blurb":"Vùng núi non và đầm lớn bao la nằm bên ngoài nơi Tiên Khâu ẩn giấu.","detail":"Khu vực này cách thành lớn gần nhất vài nghìn dặm, nhưng khoảng cách ấy mới chỉ tới vùng ngoại vi. Thạch Hạo đi sâu vào Đại Hoang trước khi ngọc bài phát sáng và chỉ đường.","theLucLienQuan":[],"nguon":["@c1230"]},{"id":"mau-vang-co-mieu","name":"Màu vàng cổ miếu","cn":"","capDo":"khac","parentId":"dinh-nui-muoi-van-truong","blurb":"Thần miếu cổ màu vàng nằm trên đỉnh núi cao mười vạn trượng. Nơi đây lưu giữ lạc ấn Đại Đạo của các sinh linh cổ đại giống Chiến thần.","detail":"Gạch ngói và tường của cổ miếu đều mang màu vàng. Các lạc ấn quanh miếu thuộc về những sinh linh từng ngồi tham kinh ngộ đạo từ thời xa xưa, tạo nên sức ép rèn luyện cực kỳ khắc nghiệt.","theLucLienQuan":["Tiên Viện","Thánh Viện"],"nguon":["@c1231"]},{"id":"khu-vuc-chien-than-lac-an","name":"Khu vực Chiến thần lạc ấn","cn":"","capDo":"khac","parentId":"dinh-nui-muoi-van-truong","blurb":"Vùng rèn luyện trước cổ miếu, nơi áp lực Đại Đạo có thể đánh nát xương cốt và hủy diệt hình thần. Người trẻ tu thành ba đạo tiên khí mới có thể dựa vào bản thân tiến gần.","detail":"Khu vực này chứa khí tức và lạc ấn của những sinh linh cổ đại giống Chiến thần. Thạch Hạo hòa vào hoàn cảnh nơi đây, chịu toàn thân Thần cốt bị đánh nát rồi tái đúc trong mười ngày.","theLucLienQuan":["Tiên Viện","Thánh Viện"],"nguon":["@c1231"]},{"id":"dinh-nui-muoi-van-truong","name":"Đỉnh núi mười vạn trượng","cn":"","capDo":"khac","parentId":null,"blurb":"Đỉnh núi cao nơi cổ miếu màu vàng và đầu Hư Không Thần Kiều tọa lạc. Phần lớn tu sĩ hai viện phải dùng bảo thuyền và bạch cốt phù mới có thể lên đây.","detail":"Áp lực trên đỉnh núi cực mạnh, khiến người không có ba đạo tiên khí khó dựa vào bản thân đứng vững. Đây là điểm tập kết của tu sĩ Tiên Viện và Thánh Viện trước khi họ tiếp tục tìm cơ duyên.","theLucLienQuan":["Tiên Viện","Thánh Viện"],"nguon":["@c1231"]},{"id":"hu-khong-than-kieu","name":"Hư Không Thần Kiều","cn":"","capDo":"khac","parentId":"dinh-nui-muoi-van-truong","blurb":"Con đường nhỏ lát đá cuội kéo dài từ đỉnh núi vào hư không. Những mảnh vụn cảm xúc của anh linh cổ đại dọc đường có thể khiến tu sĩ khóc cười hoặc phát cuồng.","detail":"Hư Không Thần Kiều dẫn về phía Tiên Khâu và một bí cảnh. Thạch Hạo đi qua nơi đây mà không bị cảm xúc cổ đại ảnh hưởng, trong khi nhiều tu sĩ hai viện mất khả năng tự chủ.","theLucLienQuan":["Tiên Viện","Thánh Viện"],"nguon":["@c1231"]},{"id":"bi-canh-cuoi-hu-khong-than-kieu","name":"Bí cảnh cuối Hư Không Thần Kiều","cn":"","capDo":"gioi-nho","parentId":"hu-khong-than-kieu","blurb":"Bí cảnh nằm ở cuối con đường quanh co xuyên qua hư không. Thạch Hạo tiến vào đây sau khi vượt qua khu vực có mảnh vụn cảm xúc của anh linh cổ đại.","detail":"Lối vào bí cảnh nối với Hư Không Thần Kiều bằng một con đường nhỏ quanh co. Nội tình và cơ duyên bên trong chưa được hé lộ trong chương này.","theLucLienQuan":[],"nguon":["@c1231"]},{"id":"son-mon-tien-khau","name":"Sơn môn Tiên khâu","cn":"","capDo":"khac","parentId":"tien-khau","blurb":"Cửa ngõ nằm giữa hai núi đá, dẫn vào khu vực sâu nhất của Tiên khâu.","detail":"Con đường hẹp trước sơn môn bị một tràng vực mạnh bao phủ, khiến các thiên tài ba đạo tiên khí khó di chuyển. Cuối đường còn có thần môn màu vàng chắn lối, sau đó bị Thạch Hạo dùng một quyền phá vỡ.","theLucLienQuan":["Tiên Viện","Thánh Viện"],"nguon":["@c1232"]},{"id":"ngon-nui-co-tru-ta-than-truc-co","name":"Ngọn núi có Trừ tà thần trúc cổ","cn":"","capDo":"khac","parentId":"tien-khau","blurb":"Ngọn núi đá nằm sâu trong Tiên khâu, nơi cây Trừ tà thần trúc cổ xưa nhất xuất hiện.","detail":"Trên đỉnh núi có một cây thần trúc trắng như tuyết. Hỗn độn chớp giật liên tục đánh xuống quanh cây, khiến khu vực trở thành một thử thách nguy hiểm đối với người muốn tiếp cận.","theLucLienQuan":[],"nguon":["@c1232"]},{"id":"dinh-nui-ich-ta-than-truc","name":"Đỉnh núi Ích Tà Thần Trúc","cn":"","capDo":"khac","parentId":"ngon-nui-co-tru-ta-than-truc-co","blurb":"Đỉnh núi nơi Ích Tà Thần Trúc mọc giữa hỗn độn và thần quang.","detail":"Nơi đây có đá tím lưu dấu ấn của Bất Hủ giả, khôi lỗi Hắc Ám tiên kim trấn giữ và một ao thần dịch hình thành dưới gốc trúc.","theLucLienQuan":[],"nguon":["@c1233"]},{"id":"khoang-dat-chay-duoi-chan-nui","name":"Khoảng đất cháy dưới chân núi","cn":"","capDo":"khac","parentId":"ngon-nui-co-tru-ta-than-truc-co","blurb":"Vùng đất trơ trụi không có cây cỏ nằm dưới chân núi thần trúc.","detail":"Vô số tàn hồn Long Tước, Ma Viên, nhện, dơi và các sinh linh khác xuất hiện tại đây, đồng loạt tìm cách xâm nhập nguyên thần và thân thể Thạch Hạo.","theLucLienQuan":[],"nguon":["@c1233"]},{"id":"vach-nui-khac-da","name":"Vách núi khắc đá","cn":"","capDo":"khac","parentId":"ngon-nui-co-tru-ta-than-truc-co","blurb":"Vách núi lưu giữ hình khắc của lão nông dẫn đường.","detail":"Sau khi từ chối tiếp tục tới gần thần trúc, lão nông hóa thành bóng mờ bay vào vách núi và trở lại hình thái một bức tranh khắc đá.","theLucLienQuan":[],"nguon":["@c1233"]},{"id":"khu-vuc-ich-ta-than-truc","name":"Khu vực Ích Tà Thần Trúc","cn":"","capDo":"khac","parentId":"dinh-nui-ich-ta-than-truc","blurb":"Khu vực đặt Ích Tà Thần Trúc, ao thần dịch và tảng đá xanh, đồng thời là một cửa ải sinh tử.","detail":"Nơi đây được ý chí quy tắc cổ xưa bảo vệ và có Hắc Ám tiên kim nhân trấn giữ. Người vượt ải phải chiến đấu bằng chân thân, không dựa vào ngoại vật, đồng thời thể hiện năng lực siêu việt mọi sinh linh cùng cấp.","theLucLienQuan":["Dị Vực","Hoàng tộc Dị Vực"],"nguon":["@c1234"]},{"id":"than-tri-ich-ta-than-truc","name":"Thần trì Ích Tà Thần Trúc","cn":"","aliases":["Ao dưới rễ Ích Tà Thần Trúc","Ao Ích Tà Thần Trúc","Thần trì dưới Ích Tà Thần Trúc"],"capDo":"khac","parentId":"khu-vuc-ich-ta-than-truc","blurb":"Ao thần dịch nằm dưới rễ Ích Tà Thần Trúc, chứa chất lỏng trắng nõn và thơm nức.","detail":"Chất lỏng trong ao có thể dùng rèn luyện thân thể. Một người trẻ tuổi Hoàng tộc Dị Vực từng vượt cửa ải và lấy thần dịch tại đây vào cuối kỷ nguyên trước.","theLucLienQuan":["Hoàng tộc Dị Vực"],"nguon":["@c1234"]},{"id":"dong-song-mau-vang","name":"Dòng sông màu vàng","cn":"","capDo":"khac","parentId":"tien-khau","blurb":"Dòng sông phát ra ánh vàng nhu hòa trong Tiên khâu.","detail":"Thạch Hạo nghi dòng nước này có liên quan đến hoàng tuyền và lần theo nó để tìm linh quả. Cuối dòng sông là nơi ba cây thực vật màu vàng sinh trưởng, trong đó một cây kết Hoàng Tuyền Quả.","theLucLienQuan":[],"nguon":["@c1237"]},{"id":"cau-da-co","name":"Cầu đá cổ","cn":"","capDo":"khac","parentId":"dong-song-mau-vang","blurb":"Cây cầu đá bắc qua dòng sông màu vàng trong Tiên khâu.","detail":"Cầu sụp xuống ngay sau khi Thạch Hạo sang bờ bên kia. Vụ sụp tạo nên sóng lớn và động tĩnh bất thường dù dòng sông không rộng hoặc sâu.","theLucLienQuan":[],"nguon":["@c1237"]},{"id":"thung-lung-thi-the-than-thanh","name":"Thung lũng thi thể thần thánh","cn":"","capDo":"khac","parentId":"tien-khau","blurb":"Thung lũng chứa năm, sáu thi thể khổng lồ vẫn tỏa ánh sáng tinh khiết sau khi chết.","detail":"Danh tính các thi thể chưa được xác nhận; Thạch Hạo chỉ suy đoán chúng có thể là Chân Tiên hoặc Bất Hủ giả của Dị Vực. Một màn sáng thần thánh bảo vệ thung lũng và đủ sức phá hủy tức thời pháp khí cấp Thiên Thần, khiến hắn quyết định rút lui.","theLucLienQuan":["Dị Vực"],"nguon":["@c1237"]},{"id":"cuoi-dong-song-vang","name":"Cuối dòng sông vàng","cn":"","capDo":"khac","parentId":"dong-song-mau-vang","blurb":"Khu vực cuối dòng sông màu vàng, nơi ráng lành dâng trào và Hoàng Tuyền Quả sinh trưởng.","detail":"Nơi đây có ba cây thực vật giống như được đúc bằng vàng ròng. Một cây đã kết quả màu hoàng kim và Thạch Hạo tiếp cận được mà chưa gặp bất kỳ sự ngăn cản nào.","theLucLienQuan":[],"nguon":["@c1237"]},{"id":"khu-vuc-cay-hoang-tuyen-qua","name":"Khu vực cây Hoàng Tuyền Quả","cn":"","capDo":"khac","parentId":"cuoi-dong-song-vang","blurb":"Khu vực cạnh dòng sông vàng có ba cây thuốc mang Hoàng Tuyền Quả và là nơi bốn Hoàng Tuyền Trùng biến chủng phục kích.","detail":"Ba cây thuốc dạng thực vật vàng óng mọc tại đây. Một cây đã hết quả, trong khi hai cây còn lại lần lượt có ba và năm quả; bốn Hoàng Tuyền Trùng sống gần thần dược và Tiên thi ngụy trang tại đây để tập kích kẻ tới hái quả.","theLucLienQuan":[],"nguon":["@c1238"]},{"id":"dai-dia-xuong-cot","name":"Đại địa xương cốt","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng đất tử tịch quanh dòng sông màu vàng, phủ kín vô số hài cốt.","detail":"Đại địa không còn sinh cơ và được lát bởi vô số xương khô, nhiều bộ đã mục nát đến mức gần hóa thành bột.","theLucLienQuan":[],"nguon":["@c1239"]},{"id":"doan-nhai-cuoi-dong-song","name":"Đoạn nhai cuối dòng sông","cn":"","capDo":"khac","parentId":"cuoi-dong-song-vang","blurb":"Đoạn nhai nơi dòng sông màu vàng đổ xuống vực tối bên dưới.","detail":"Đây là phần cuối Thạch Hạo nhìn thấy của dòng sông màu vàng. Nước sông đổ khỏi đoạn nhai vào một miệng núi lửa khổng lồ mà không phát ra tiếng động.","theLucLienQuan":[],"nguon":["@c1239"]},{"id":"hoang-tuyen-dia-nguc","name":"Hoàng Tuyền Địa ngục","cn":"","aliases":["Địa Ngục trong trải nghiệm Hoàng Tuyền quả"],"capDo":"gioi-nho","parentId":null,"blurb":"Thế giới tử vong mà Thạch Hạo trải nghiệm sau khi dùng Hoàng Tuyền Quả.","detail":"Nơi này gồm đại địa vô tận phủ hàng ngàn tỉ bộ xương, một vực sâu có lực thôn phệ và thế giới ngầm chứa biển dung nham cùng nhiều hình phạt dành cho Ma thần, ác quỷ và sinh linh mang Tiên Đạo khí tức. Thạch Hạo xác định cảnh tượng là sự tôi luyện tinh thần do Hoàng Tuyền Quả tạo ra, nhưng cảm giác đau đớn trong đó sống động đến mức khó phân biệt thật giả.","theLucLienQuan":[],"nguon":["@c1240"]},{"id":"mieng-nui-lua-dia-nguc","name":"Miệng núi lửa Địa ngục","cn":"","capDo":"khac","parentId":"hoang-tuyen-dia-nguc","blurb":"Vực sâu nằm ở cuối đại địa xương cốt trong Hoàng Tuyền Địa ngục.","detail":"Bên trong vực có Ma thần mang gông xiềng, ác quỷ mục rữa và dung nham đủ sức thiêu hủy chúng. Khi bạo động, vực sâu phun bạch cốt, âm vụ và quỷ quái rồi tạo ra lực hút cuốn núi non, hài cốt cùng Thạch Hạo xuống thế giới ngầm.","theLucLienQuan":[],"nguon":["@c1240"]},{"id":"bien-dung-nham-dia-nguc","name":"Biển dung nham Địa ngục","cn":"","capDo":"khac","parentId":"hoang-tuyen-dia-nguc","blurb":"Biển dung nham mênh mông nằm trong thế giới ngầm của Hoàng Tuyền Địa ngục.","detail":"Dung nham có thể thiêu hủy núi đá, Ma thần và huyết nhục của sinh linh mang Tiên Đạo khí tức. Phía trên biển trôi nổi đảo bạch cốt, đại lục đen và các cung điện cổ gắn với những hình phạt đáng sợ.","theLucLienQuan":[],"nguon":["@c1240"]},{"id":"dao-bach-cot","name":"Đảo bạch cốt","cn":"","capDo":"khac","parentId":"bien-dung-nham-dia-nguc","blurb":"Những đảo nhỏ cấu thành từ xương trắng trôi nổi trên biển dung nham Địa ngục.","detail":"Các đảo có thể nổi lên, chìm xuống hoặc tan rã giữa dung nham. Một đảo bạch cốt đã nâng Thạch Hạo lên rồi phóng xiềng xích khóa cổ cùng tứ chi hắn trước khi hình phạt phân thây được thi hành.","theLucLienQuan":[],"nguon":["@c1240"]},{"id":"the-gioi-mat-phap-trong-doi-chuyen-sinh","name":"Thế giới mạt pháp trong một đời chuyển sinh","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Một thế giới thiếu tinh khí mà Thạch Hạo tiến vào trong đời chuyển sinh đầu tiên được kể rõ.","detail":"Thạch Hạo mang theo ký ức khi nhập thai tại đây và cố vận chuyển Nguyên Thủy Chân Giải cùng Liễu Thần pháp. Hắn chỉ hấp thu được một phần bổn nguyên tinh hoa khi còn trong thai, còn sau khi chào đời thì hoàn cảnh mạt pháp khiến việc tu luyện gần như không thể tiếp tục.","theLucLienQuan":[],"nguon":["@c1241"]},{"id":"khu-vuc-ba-cay-hoang-tuyen-qua","name":"Khu vực ba cây Hoàng Tuyền quả","cn":"","capDo":"khac","parentId":"khu-vuc-cay-hoang-tuyen-qua","blurb":"Nơi thân thể Thạch Hạo đứng trong lúc ý thức trải qua đại mộng Hoàng Tuyền.","detail":"Khu vực có ba cây phát ra kim quang thần thánh và treo nhiều quả Hoàng Tuyền. Thạch Hạo trở lại nơi này sau khi thế giới Địa Ngục cùng những đời chuyển sinh sụp đổ.","theLucLienQuan":[],"nguon":["@c1241"]},{"id":"bai-da-tien-khau","name":"Bãi đá Tiên khâu","cn":"","capDo":"khac","parentId":"tien-khau","blurb":"Bãi đá sâu trong Tiên khâu, nơi Thạch Hạo gặp lại lão nông và phát hiện biển anh linh bị phong ấn.","detail":"Khu vực có những khối đá mang hình thiên kiếm, trâu nằm và Côn Bằng giương cánh, được Tiên vụ bao phủ. Núi đá tại đây ngăn cách Thạch Hạo với vùng âm vụ chứa vô số anh linh.","theLucLienQuan":["Đội quân anh linh Tiên khâu"],"nguon":["@c1242"]},{"id":"co-dia-duoi-tien-khau","name":"Cổ địa dưới Tiên khâu","cn":"","capDo":"khac","parentId":"tien-khau","blurb":"Khu vực sâu dưới Tiên khâu, nơi một Chí Tôn anh linh từ kỷ nguyên Tiên cổ được cho là đang ngủ say.","detail":"Lão nông cảnh báo dưới cổ địa còn có một tồn tại đáng sợ hơn những anh linh đã hiện diện. Tồn tại này đã trở thành Chí Tôn anh linh từ kỷ nguyên Tiên cổ.","theLucLienQuan":["Đội quân anh linh Tiên khâu"],"nguon":["@c1242"]},{"id":"luan-hoi-lo","name":"Luân Hồi lộ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian thần bí trong trải nghiệm của người ăn Hoàng Tuyền Quả.","detail":"Thái Âm Ngọc Thỏ thấy một chiếc mâm muốn đưa mình vãng sinh, Đại đỉnh vượt dòng thời gian, nhiều cảnh đại chiến và một bóng người quen thuộc tại nơi này.","theLucLienQuan":[],"nguon":["@c1243"]},{"id":"gioi-hai","name":"Giới hải","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng biển giữa các giới xuất hiện trong phần ký ức đứt đoạn của Thái Âm Ngọc Thỏ.","detail":"Thái Âm Ngọc Thỏ nhớ được lời nói về một người cô độc từng vượt giới hải, đi xuyên vùng hắc ám và hóa giải quỷ dị cùng điềm không lành, nhưng danh tính và nội dung quan trọng đã bị thời gian xóa mờ.","theLucLienQuan":[],"nguon":["@c1244"]},{"id":"linh-son-cua-thien-than-thu-vien","name":"Linh sơn của Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Linh sơn nơi Đại trưởng lão chuẩn bị điều kiện cho Thạch Hạo bế quan lấy thân làm chủng.","detail":"Tại chân núi, Đại trưởng lão bố trí nhiều dược trì, đại đỉnh nấu lão dược cùng các tài nguyên cần thiết để hỗ trợ lần đột phá của Thạch Hạo.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1244"]},{"id":"khu-vuc-be-quan-sau-trong-thien-than-thu-vien","name":"Khu vực bế quan sâu trong Thiên Thần thư viện","cn":"","capDo":"khac","parentId":"thien-than-thu-vien","blurb":"Khu vực sâu trong Thiên Thần thư viện được Đại trưởng lão dùng làm nơi bế quan cho Thạch Hạo.","detail":"Nơi này được đại trận che kín và cấm người ngoài tới gần trong suốt nửa năm Thạch Hạo tu luyện. Vì không có người qua lại, cỏ dại quanh khu vực mọc cao quá đầu người.","theLucLienQuan":["Thiên Thần thư viện"],"nguon":["@c1246"]},{"id":"linh-chan-nui","name":"Linh chân núi","cn":"","capDo":"khac","parentId":"linh-son-cua-thien-than-thu-vien","blurb":"Địa điểm Đại trưởng lão tiến hành quá trình luyện thể và luyện nguyên thần cho Thạch Hạo.","detail":"Tại đây, Thạch Hạo trải qua dược trì, kịch độc, binh khí luyện thể, tạo rồi dung luyện nguyên thần thứ hai và đối kháng Hồn khí dưới sự chỉ dẫn của Đại trưởng lão.","theLucLienQuan":["Thiên Thần thư viện"],"nguon":["@c1246"]},{"id":"tao-hoa-dia-chon-loai","name":"Tạo hóa địa chôn loại","cn":"","capDo":"khac","parentId":"cuu-thien","blurb":"Vùng tạo hóa được Đại trưởng lão chọn để chôn kỳ dị hạt giống chứa Thạch Hạo.","detail":"Đại trưởng lão dự định đưa kỳ dị hạt giống đã được Bù thiên dược phong kín tới đây chôn xuống, chờ Thạch Hạo hoàn thành quá trình siêu thoát và thăng hoa sinh mệnh.","theLucLienQuan":["Thiên Thần thư viện"],"nguon":["@c1247"]},{"id":"thanh-vi-thien","name":"Thanh Vi Thiên","cn":"","capDo":"vuc","parentId":"cuu-thien","blurb":"Một trong Cửu Thiên, nơi Đại trưởng lão đưa Thạch Hạo tới để thực hiện bước tu hành lấy thân làm chủng.","detail":"Thanh Vi Thiên nằm ngoài Vô Lượng Thiên và có một cổ địa tràn ngập tiên thiên thổ khí. Đại trưởng lão chọn nơi này để chôn Thạch Hạo như một hạt giống, dùng bản nguyên thiên địa nuôi dưỡng quá trình tu hành.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1248"]},{"id":"co-dia-tho-khi-thanh-vi-thien","name":"Cổ địa thổ khí tại Thanh Vi Thiên","cn":"","capDo":"khac","parentId":"thanh-vi-thien","blurb":"Một cổ địa phủ đầy thổ khí vàng vọt tại Thanh Vi Thiên, được Đại trưởng lão chọn làm nơi nuôi dưỡng Thạch Hạo.","detail":"Khí vàng ở đây không phải bụi đất thông thường mà là tiên thiên tinh khí đậm đặc. Thạch Hạo được chôn trong khu vực này cùng hạt giống kỳ dị để tiếp nhận sự tẩm bổ của bản nguyên thiên địa.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1248"]},{"id":"khong-gian-ben-trong-thien-dia-ky-di-hat-giong","name":"Không gian bên trong Thiên Địa kỳ dị hạt giống","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian thai nghén nữ Tiên Thai và chứa Thiên Địa Thai Bàn, hoàn toàn ngăn cách sự dò xét từ bên ngoài.","detail":"Không gian nằm trong Thiên Địa kỳ dị hạt giống, nơi nữ Tiên Thai được trời đất thai nghén và Thiên Địa Thai Bàn tọa lạc. Khu vực này ngăn cách trong ngoài nhưng liên kết sâu với pháp tắc thiên địa, cho phép Chư Thiên vạn đạo hội tụ khi Thạch Hạo bắt đầu tu hành.","theLucLienQuan":[],"nguon":["@c1249"]},{"id":"trung-tam-thien-dia-cuong-ron","name":"Trung tâm thiên địa cuống rốn","cn":"","capDo":"khac","parentId":"khong-gian-ben-trong-thien-dia-ky-di-hat-giong","blurb":"Vị trí trung tâm bên trong Thiên Địa kỳ dị hạt giống, nơi thiên địa giao thái và thai nghén tiên thai. Phiến đá tại đây che chở Thạch Hạo, giúp hắn tạm tránh phản phệ khi tiếp xúc với bí mật bản nguyên.","detail":"Nơi này phô bày những trật tự căn bản nhất của thiên địa và cho phép Thạch Hạo quan sát, phân giải rồi tái tổ hợp các hạt quy tắc. Sự che chở của phiến đá trung tâm chỉ có tính tạm thời; nếu hành động lấy bản nguyên bị đại thiên địa phát hiện, hắn vẫn có thể đối mặt với phản phệ hoặc trừng phạt.","theLucLienQuan":[],"nguon":["@c1250"]},{"id":"can-khon-trong-than-the-thach-hao","name":"Càn Khôn trong thân thể Thạch Hạo","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Nội giới được Thạch Hạo xác lập khi xem thân thể mình là một càn khôn hoàn chỉnh.","detail":"Trong cách diễn giải này, hình thể Thạch Hạo đối ứng với đại vũ trụ, còn tinh thần, huyết dịch, gân mạch, xương và máu thịt trở thành những bộ phận cấu thành thể nội đạo.","theLucLienQuan":[],"nguon":["@c1251"]},{"id":"cac-canh-cua-trong-co-the-thach-hao","name":"Các cánh cửa trong cơ thể Thạch Hạo","cn":"","capDo":"khac","parentId":"can-khon-trong-than-the-thach-hao","blurb":"Những môn hộ chứa tiềm năng và Nội Đạo của cơ thể Thạch Hạo.","detail":"Các cánh cửa chỉ hé mở trong thời gian ngắn, phát ra thanh quang có thể đối kháng đại đạo bên ngoài rồi khép lại và để lại những khe nhỏ. Thanh quang từ chúng sau đó đan xen thành hạt giống tự thân của Thạch Hạo.","theLucLienQuan":[],"nguon":["@c1252"]},{"id":"dai-can-khon","name":"Đại Càn Khôn","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Đại vũ trụ bên ngoài có thể thai nghén đạo chủng hoàn mỹ và dùng quy tắc che chở người dung hợp.","detail":"Đại Càn Khôn đại diện cho hệ thống đại đạo và quy tắc bên ngoài thân thể. Thạch Hạo không lựa chọn dung hợp hoàn toàn với hạt giống do nơi này thai nghén mà quyết định dựa vào thân thể cùng tinh thần của chính mình.","theLucLienQuan":[],"nguon":["@c1252"]},{"id":"hoa-dong-tai-vo-luong-thien","name":"Hỏa động tại Vô Lượng Thiên","cn":"","capDo":"khac","parentId":"vo-luong-thien","blurb":"Cổ động hỏa đạo tại Vô Lượng Thiên, nơi hỏa lực đủ sức thiêu chết Giáo Chủ thông thường.","detail":"Bên trong hỏa động có Thái Dương chi tinh, mạng lưới cung điện ngầm, hài cốt của những sinh linh vượt trên Giáo Chủ cảnh và một hố tro cốt. Nơi đây từng là chỗ ở của một vị Đế Quân; Đại trưởng lão đào được từ hố tro một sinh linh hình người có cánh vẫn còn sống.","theLucLienQuan":[],"nguon":["@c1253"]},{"id":"chien-truong-giao-dau-cua-cac-chi-ton-tre-tuoi","name":"Chiến trường giao đấu của các Chí Tôn trẻ tuổi","cn":"","capDo":"khac","parentId":"chien-truong","blurb":"Khu vực diễn ra cuộc đối đầu giữa Thạch Hạo với Lam tiên, Đại tu đà và Tử Nhật Thiên Quân. Nhiều thần thông, kinh văn tinh thần và va chạm thân thể liên tục phá vỡ hư không tại đây.","detail":"Chiến trường chịu sự công phạt của chín đại thần thông, vạn linh do tinh hà diễn hóa, Phật Đà tâm kinh, Lôi Đế ấn và trật tự thần liên. Cuộc giao tranh trở thành màn tranh phong tối cao giữa các Chí Tôn trẻ tuổi.","theLucLienQuan":["Tiên viện","Thiên Thần thư viện","Vương gia"],"nguon":["@c1254"]},{"id":"tien-phu-duoi-ao-bun","name":"Tiên phủ dưới ao bùn","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một thế giới dưới lòng đất được che giấu bên dưới ao bùn. Khi lối vào mở, tiên quang, tiên nhạc và tiếng cửa đá lập tức thu hút các Chí tôn trẻ tuổi.","detail":"Một đòn đánh làm ao bùn sụp đổ, tiên quang bốc lên và cửa đá mở ra, để lộ thế giới dưới lòng đất. Nhiều Chí tôn trẻ tuổi lập tức lao xuống tranh đoạt cơ duyên, sau đó Thạch Hạo gọi đồng bạn và đệ tử Thiên Thần thư viện cùng tiến vào.","theLucLienQuan":["Thiên Thần thư viện","Tiên Viện"],"nguon":["@c1256"]},{"id":"chien-truong-canh-ao-bun","name":"Chiến trường cạnh ao bùn","cn":"","capDo":"khac","parentId":"tien-phu-duoi-ao-bun","blurb":"Khu vực nơi Thạch Hạo đối đầu ba Chí tôn trẻ tuổi trước khi Tiên phủ mở ra.","detail":"Tại đây, Thạch Hạo áp đảo Tử Nhật Thiên Quân và chống lại sự liên thủ của Đại Tu Đà cùng Lam Tiên. Hắn cũng cảm nhận được nhiều khí tức Chí tôn trẻ tuổi mới xuất hiện quanh ao bùn.","theLucLienQuan":["Tiên Viện","Thiên Thần thư viện"],"nguon":["@c1256"]},{"id":"tien-thanh","name":"Tiên Thành","cn":"","aliases":["Tiên thành dưới lòng đất","Tòa thành kim loại","Thanh kim cự thành"],"capDo":"thanh","parentId":"tien-phu-duoi-ao-bun","blurb":"Tiên Thành là cự thành thanh kim nằm sâu dưới lòng đất Tiên phủ. Thành chứa chín ngọn núi đá cùng các cổ động phủ dâng tiên khí và tự mở cửa sau thời gian dài đóng kín.","detail":"Tòa thành kim loại thanh kim không bị ăn mòn sau vô số năm. Bên trong có chín ngọn núi đá, mỗi ngọn chứa cổ động phủ dâng tiên khí, tương ứng với chín đại tiên phủ. Tường thành từng có phù văn đủ sức giết Chí tôn vượt qua, nhưng khi thành xuất thế, thanh kim môn và thạch môn tự mở còn phù văn bảo hộ biến mất. Đại trưởng lão Thiên Thần Thư Viện đã phát hiện nơi này từ trước nhưng chưa từng tiến vào.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1257","@c1261"]},{"id":"ao-bun-cua-vao-long-dat-tien-phu","name":"Ao bùn cửa vào lòng đất Tiên phủ","cn":"","aliases":["Ao bùn"],"capDo":"khac","parentId":"chien-truong-canh-ao-bun","blurb":"Ao bùn là lối dẫn xuống khu vực Tiên phủ nằm sâu dưới lòng đất. Trung tâm ao nứt thành một động lớn, từ đó tiên khí không ngừng bốc lên.","detail":"Bên dưới ao bùn là đại động đá sâu thẳm và trống trải, có nhiều thạch nhũ xán lạn. Địa tầng dưới khu vực này sụp vỡ, làm lộ Tiên Thành thanh kim cùng chín ngọn núi đá chứa cổ động phủ.","theLucLienQuan":["Thiên Thần Thư Viện"],"nguon":["@c1257"]},{"id":"cua-tien-thanh","name":"Cửa Tiên Thành","cn":"","capDo":"khac","parentId":"tien-thanh","blurb":"Cửa thành cao lớn như núi Thái Cổ, nơi mọi người phải trải qua kiểm tra trước khi được tiến vào Tiên Thành.","detail":"Người thủ thành dùng mắt dọc và xích quang tại đây để xét huyết mạch, phân biệt hậu duệ di dân Tiên cổ với sinh linh dị vực, đồng thời ngăn những người quá già tiếp cận cơ duyên.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện","Thánh Viện"],"nguon":["@c1258"]},{"id":"ho-dan-hon-lien","name":"Hồ Dẫn Hồn Liên","cn":"","capDo":"khac","parentId":"tien-thanh","blurb":"Hồ nước nằm tại một quảng trường nhỏ cuối con đường bên trong Tiên Thành, nơi ba cây Dẫn Hồn Liên cùng sinh trưởng.","detail":"Nước hồ chứa dược tính bồi bổ nguyên thần của Dẫn Hồn Liên. Đây cũng là nơi sinh vật nhỏ bí ẩn tự nhận đang tắm và đánh ngất Tào Vũ Sinh.","theLucLienQuan":[],"nguon":["@c1258","@c1262"]},{"id":"dong-phu-tren-nui-da","name":"Động phủ trên núi đá","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực trọng yếu nằm trên ngọn núi đá có tiên khí bốc lên từng sợi. Nguyên Mẫu Đỉnh được đặt tại đây để thử tư cách tranh truyền thừa hạch tâm.","detail":"Động phủ do các lão binh Tiên Cổ canh giữ, gắn với việc bảo tồn hỏa chủng, hậu duệ Vương giả và truyền thừa quan trọng. Sau lời tranh luận của Lam Tiên, nơi đây trở thành địa điểm tổ chức thử thách nâng Nguyên Mẫu Đỉnh.","theLucLienQuan":["Thiên Thần Thư Viện","Thánh Viện"],"nguon":["@c1259"]},{"id":"sao-huyet-thien-giac-nghi-tai-tien-co-di-dia","name":"Sào huyệt Thiên Giác Nghĩ tại Tiên Cổ di địa","cn":"","capDo":"khac","parentId":"tien-co-di-dia","blurb":"Một sào huyệt của Thiên Giác Nghĩ từng xuất hiện khi Tiên Cổ di địa tại Ba Ngàn Châu mở ra. Trích Tiên đã tiến vào nơi này và bị nghi nhận được truyền thừa lực cực điểm.","detail":"Thạch Hạo nhớ lại Trích Tiên từng tiến vào sào huyệt, giết rất nhiều người và sau đó có thể đã nắm giữ bảo thuật lực cực điểm cùng một chiếc cổ giác thần bí. Sự xuất hiện của Thiên Giác Nghĩ nhỏ tại động phủ hiện thời cho thấy di sản của tộc này không chỉ tập trung tại một nơi.","theLucLienQuan":[],"nguon":["@c1259"]},{"id":"ngon-nui-dat-nguyen-mau-dinh","name":"Ngọn núi đặt Nguyên Mẫu Đỉnh","cn":"","capDo":"khac","parentId":"tien-thanh","blurb":"Một trong chín ngọn núi đá của Tiên Thành, nơi đặt hình chiếu Nguyên Mẫu Đỉnh.","detail":"Ngọn núi mang khí thế khiến người kính sợ như đỉnh cao Tiên Đạo. Những bậc đá xanh dẫn lên đỉnh, nơi hình chiếu Nguyên Mẫu Đỉnh được dùng để kiểm nghiệm sức mạnh thân thể.","theLucLienQuan":[],"nguon":["@c1260"]},{"id":"tien-son-dat-co-dinh","name":"Tiên sơn đặt cổ đỉnh","cn":"","capDo":"khac","parentId":"tien-thanh","blurb":"Ngọn tiên sơn đặt hình chiếu cổ đỉnh dùng cho khảo nghiệm sức mạnh thân thể.","detail":"Trên núi có tiên gia trận pháp, nhưng toàn bộ ngọn núi vẫn rung chuyển dữ dội khi Thạch Hạo nâng rồi đặt hình chiếu cổ đỉnh xuống.","theLucLienQuan":[],"nguon":["@c1261"]},{"id":"chien-truong-nam-xua-cua-thien-giac-nghi","name":"Chiến trường năm xưa của Thiên Giác Nghĩ","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Thiên Giác Nghĩ đời trước từng tử chiến với nhiều sinh linh bất hủ.","detail":"Thiên Giác Nghĩ chịu thương thế chí mạng và chảy đến giọt máu cuối cùng tại chiến trường này. Đây là một trong ba nơi Bất Diệt Kinh có thể đã thất lạc cùng những vật ông mang theo.","theLucLienQuan":[],"nguon":["@c1261"]},{"id":"vung-cam-thuoc-cuu-thien-thap-dia","name":"Vùng cấm thuộc Cửu Thiên Thập Địa","cn":"","capDo":"khac","parentId":"cuu-thien-thap-dia","blurb":"Một vùng cấm chưa được xác định cụ thể, được suy đoán có thể là nơi Bất Diệt Kinh đang thất lạc.","detail":"Thủ lĩnh lão binh liệt kê một vùng cấm nào đó thuộc Cửu Thiên Thập Địa là khả năng thứ ba về tung tích của Bất Diệt Kinh.","theLucLienQuan":["Cửu Thiên Thập Địa"],"nguon":["@c1261"]},{"id":"co-thanh-bao-la","name":"Cổ thành bao la","cn":"","capDo":"thanh","parentId":null,"blurb":"Cổ thành rộng lớn chứa chín tòa tiên sơn, hồ Dẫn Hồn liên và nhiều khu vực cất giữ cơ duyên.","detail":"Ngoài động phủ được dành riêng cho Thạch Hạo, những nơi khác trong thành còn có dược thảo và thần thạch để người tiến vào thu lấy tùy theo cơ duyên.","theLucLienQuan":[],"nguon":["@c1262"]},{"id":"chin-toa-tien-son","name":"Chín tòa tiên sơn","cn":"","capDo":"khac","parentId":"co-thanh-bao-la","blurb":"Chín núi đá tỏa tiên khí trong cổ thành, có vẻ tương ứng với chín động phủ.","detail":"Đoàn người được yêu cầu rời khỏi tiên sơn chứa động phủ dành cho Thạch Hạo. Các lão binh sau đó dẫn hắn tới nơi tìm kiếm Bất Diệt kinh.","theLucLienQuan":[],"nguon":["@c1262"]},{"id":"dong-phu-thien-giac-nghi","name":"Động phủ Thiên Giác Nghĩ","cn":"","capDo":"khac","parentId":"chin-toa-tien-son","blurb":"Cổ địa cung nằm trong một tiên sơn, là nơi Thạch Hạo được phép một mình tiến vào tìm Bất Diệt kinh.","detail":"Bên trong có vô số hang động nối nhau như mê cung và một số tiên vật rất nặng. Thạch Hạo cùng Thiên Giác Nghĩ nhỏ tìm kiếm suốt một ngày một đêm nhưng chưa phát hiện kinh văn.","theLucLienQuan":[],"nguon":["@c1262"]},{"id":"co-lo-sau-canh-cua-vach-da","name":"Cổ lộ sau cánh cửa vách đá","cn":"","capDo":"khac","parentId":"dong-phu-thien-giac-nghi","blurb":"Lối bí mật nằm sâu trong động phủ Thiên Giác Nghĩ, được mở bằng chiếc sừng vàng chưa trưởng thành của Thiên Giác Nghĩ nhỏ.","detail":"Phía sau cửa có máu nhiều màu, vảy, lông chim, quái sừng và những phần thi thể mang uy thế khủng khiếp. Thạch Hạo thấy chân cùng đầu của một con kiến vàng khổng lồ và nghi đây là tuyệt địa của trận tử chiến năm xưa.","theLucLienQuan":[],"nguon":["@c1262"]},{"id":"noi-luu-giu-bat-diet-kinh","name":"Nơi lưu giữ Bất Diệt kinh","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm chưa được gọi tên, nơi lưu giữ toàn bộ Bất Diệt kinh. Thiên Giác Nghĩ truyền cho Thạch Hạo một khắc dấu để chỉ đường tới đây.","detail":"Thiên Giác Nghĩ hy vọng Thạch Hạo tới địa điểm này và mang toàn bộ cổ kinh ra ngoài, tránh để lại tiếc nuối như ông. Vị trí và đặc điểm cụ thể của nơi này chưa được tiết lộ.","theLucLienQuan":[],"nguon":["@c1264"]},{"id":"than-ho-toa-nui-thu-hai","name":"Thần hồ","cn":"","aliases":["Thần hồ tòa núi thứ hai"],"capDo":"khac","parentId":"chin-toa-tien-son","blurb":"Hồ nước phủ hơi sương gần tòa núi thứ hai, từng là nơi tắm rửa của Tiểu Thiên Giác Nghĩ và có thần dược sinh trưởng.","detail":"Gần thần hồ có vũng bùn hình thành từ một vườn thuốc mục nát, mang hiệu quả thoát thai hoán cốt. Nơi sâu nhất của tòa núi thứ hai chỉ cho phép Tiểu Kỳ Lân trắng tiến vào để nhận những gì Kỳ Lân đại nhân lưu lại cho hậu đại.","theLucLienQuan":["Thập Hung"],"nguon":["@c1265"]},{"id":"dong-phu-tien-vuong-duoi-long-dat","name":"Động phủ Tiên Vương dưới lòng đất","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Động phủ dưới lòng đất nơi Thạch Hạo đưa Thiên Giác Nghĩ ra ngoài.","detail":"Sự xuất hiện của hậu duệ thuần huyết Thập Hung từ động phủ khiến các thư viện và Trường Sinh thế gia tập trung tranh giành Thiên Giác Nghĩ.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện","Thánh Viện","Vương gia","Phong tộc"],"nguon":["@c1266"]},{"id":"thai-so-co-quang","name":"Thái Sơ Cổ Quáng","cn":"","capDo":"khac","parentId":null,"blurb":"Một cổ quáng nguy hiểm chứa Sinh Mệnh Chi Thạch. Vương gia từng định đưa Thạch Hạo vào đây khai thác khoáng vật và chịu chết.","detail":"Địa danh được nhắc lại khi quá khứ Thạch Hạo từng bị Vương gia biến thành người đào quáng bị khơi ra.","theLucLienQuan":["Vương gia"],"nguon":["@c1267"]},{"id":"bac-hai-bai-da","name":"Bắc Hải bãi đá","cn":"","capDo":"khac","parentId":"bac-hai","blurb":"Bãi đá cổ giữa Bắc Hải và là mục tiêu trong hành trình tìm Bất Diệt Kinh của Thạch Hạo.","detail":"Bắc Hải bãi đá tồn tại từ lâu giữa biển, có thần bích nơi nhiều chí tôn trẻ tuổi từng khắc tên để biểu lộ thực lực và so sánh với các tiên hiền.","theLucLienQuan":[],"nguon":["@c1268"]},{"id":"hai-vuc-tu-vong-phu-suong-den","name":"Hải vực tử vong phủ sương đen","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển đen vô hạn, tuyệt đối tĩnh lặng và bị bao phủ bởi sương mù dày đặc.","detail":"Nơi đây không có tiếng sóng hay bọt nước. Sau ba ngày di chuyển, sương mù dày đến mức nhãn thuật của Thạch Hạo mất hiệu lực.","theLucLienQuan":[],"nguon":["@c1269"]},{"id":"hai-vuc-hai-cot-khong-lo","name":"Hải vực hài cốt khổng lồ","cn":"","capDo":"vuc","parentId":"hai-vuc-tu-vong-phu-suong-den","blurb":"Khu biển phủ sương với vô số hài cốt khổng lồ nhô lên khỏi mặt nước.","detail":"Những đầu lâu, cẳng tay và bộ xương khổng lồ cho thấy nơi đây từng xảy ra cuộc chiến giữa các tồn tại tuyệt đỉnh. Thạch Hạo cảm nhận khu vực này như một thông đạo tử vong dẫn tới Minh giới.","theLucLienQuan":[],"nguon":["@c1269"]},{"id":"bac-hai-thach-lam","name":"Bắc Hải Thạch Lâm","cn":"","capDo":"vuc","parentId":"bac-hai","blurb":"Điểm đến dự kiến của hành trình bằng Minh Thuyền.","detail":"Thạch Hạo xác định vùng biển xanh và các địa vực dị thường mà Minh Thuyền đi vào không giống Bắc Hải Thạch Lâm, cho thấy con thuyền đã lệch khỏi tuyến đường được biết đến.","theLucLienQuan":[],"nguon":["@c1269"]},{"id":"the-gioi-dao-nguoc","name":"Thế giới đảo ngược","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Địa vực kỳ dị có mặt trời nằm sát biển, còn núi non, lục địa và sinh linh đều hiện diện trên bầu trời theo trạng thái đảo ngược.","detail":"Minh Thuyền tiến vào nơi này sau khi rời biển chết. Cây cối mọc ngược trên thiên không, còn hung cầm và mãnh thú di chuyển trong khung cảnh trái ngược với thế giới thông thường.","theLucLienQuan":[],"nguon":["@c1269"]},{"id":"thien-dia-mat","name":"Thiên Địa mắt","cn":"","capDo":"khac","parentId":null,"blurb":"Vòng xoáy sấm sét nối liền bầu trời và mặt biển, chứa vô số mảnh vỡ thời gian.","detail":"Thiên Địa mắt vận hành ngược với Hải Nhãn thông thường, phát ra tiếng sấm công kích nguyên thần và tạo lực hút kéo sinh linh lên phía thiên khung. Người bị cuốn vào có nguy cơ chết già giữa đường thời gian hoặc biến mất trong Luân Hồi.","theLucLienQuan":[],"nguon":["@c1269"]},{"id":"duong-noi-thoi-gian","name":"Đường nối thời gian","cn":"","capDo":"khac","parentId":null,"blurb":"Một đường nối hình thành từ thời gian lưu chuyển và khí tức năm tháng, nằm giữa vùng lôi đình kinh khủng.","detail":"Lối vào mang hình thái vòng xoáy thông thiên, xung quanh có lôi đình đủ sức vượt xa thiên kiếp. Trường vực tại đây kéo cả minh thuyền lẫn người trên thuyền vào quang đạo, nơi sức mạnh năm tháng có thể khiến thân thể già đi hàng vạn năm rồi đảo ngược trở lại. Điểm đến và thời đại ở đầu kia chưa được xác định.","theLucLienQuan":[],"nguon":["@c1270"]},{"id":"hai-vuc-sam-set","name":"Hải vực sấm sét","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển đầy lôi đình khổng lồ bao quanh đường nối thời gian.","detail":"Lôi đình tại hải vực trải rộng như ngân hà và có uy lực vượt xa thiên kiếp, trong khi sóng biển dâng cao hàng nghìn tầng. Trên vòm trời còn hiện ra cảnh tượng núi non, cây cỏ và Đại thế giới đứng ngược.","theLucLienQuan":[],"nguon":["@c1270"]},{"id":"con-bang-sao-huyet","name":"Côn Bằng sào huyệt","cn":"","capDo":"khac","parentId":null,"blurb":"Sào huyệt của Côn Bằng, nơi Thạch Hạo từng bắt gặp những chiếc thuyền giấy bí ẩn.","detail":"Tại đây từng có một cánh cửa ánh sáng đưa những chiếc thuyền giấy trôi theo dòng sông thời gian, khiến Thạch Hạo liên tưởng chúng với Bạch y nữ Đế.","theLucLienQuan":[],"nguon":["@c1271"]},{"id":"hai-vuc-xanh-lam","name":"Hải vực xanh lam","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển xanh trong và phẳng lặng nơi Thạch Hạo cùng Thiên Giác Nghĩ nhỏ tỉnh lại.","detail":"Thạch Hạo và Thiên Giác Nghĩ nhỏ bị đánh bật khỏi đường nối thời gian rồi tỉnh lại tại vùng biển xanh lam phẳng lặng như gương. Từ đây, họ lên minh thuyền bằng xương để tiếp tục hành trình.","theLucLienQuan":[],"nguon":["@c1272"]},{"id":"bien-chet","name":"Biển chết","cn":"","capDo":"vuc","parentId":null,"blurb":"Hải vực tử khí phủ khói đen, mang minh giới khí tức và có nhiều hài cốt khổng lồ.","detail":"Minh thuyền bằng xương đưa Thạch Hạo và Thiên Giác Nghĩ nhỏ băng qua vùng biển đầy khói đen, tử khí và những bộ hài cốt khổng lồ trồi lên khỏi mặt nước trước khi trở lại khu vực có sinh khí.","theLucLienQuan":[],"nguon":["@c1272"]},{"id":"sieu-tuyet-phong-sam-set","name":"Siêu tuyệt phong sấm sét","cn":"","capDo":"khac","parentId":"bac-hai-bai-da","blurb":"Một siêu tuyệt phong tại Bắc Hải bãi đá, quanh núi có chớp giật và dấu ấn đại đạo.","detail":"Ngọn núi được sấm chớp bao quanh, lưu giữ phù văn cùng dấu ấn đại đạo của tiên hiền cổ đại. Người có thể leo tới đỉnh có cơ hội lĩnh ngộ đạo pháp nơi đây.","theLucLienQuan":[],"nguon":["@c1272"]},{"id":"sieu-tuyet-phong-co-kim-o","name":"Siêu tuyệt phong cổ Kim ô","cn":"","capDo":"khac","parentId":"bac-hai-bai-da","blurb":"Ngọn trụ đá cao xuyên mây tại Bắc Hải bãi đá, nơi đặt thi thể một con Kim ô cổ.","detail":"Thi thể cổ Kim ô nằm ngang trên đỉnh và tỏa ra Thái Dương hỏa tinh, khiến khu vực phụ cận trở thành tiểu cấm địa mà người bình thường khó tiếp cận.","theLucLienQuan":[],"nguon":["@c1272"]},{"id":"sieu-tuyet-phong","name":"Siêu Tuyệt phong","cn":"","capDo":"khac","parentId":"bac-hai-thach-lam","blurb":"Hệ thống núi thí luyện tại Bắc Hải thạch lâm, mỗi tòa đều có pháp trận cổ khảo nghiệm người đăng phong.","detail":"Các Siêu Tuyệt phong phát động công kích tương ứng hoặc vượt cảnh giới của người đăng phong. Chúng được phân cấp theo khoảng thời gian chưa có ai chinh phục, từ vài vạn năm tới hơn trăm vạn năm.","theLucLienQuan":[],"nguon":["@c1273"]},{"id":"noi-thi-luyen-chung-cuc","name":"Nơi thí luyện chung cực","cn":"","aliases":["Nơi thí luyện cuối cùng","Chung cực nơi tập luyện"],"capDo":"khac","parentId":"bac-hai-thach-lam","blurb":"Địa điểm thí luyện đặc biệt nằm trong Bắc Hải thạch lâm và được người bản địa xem như một vùng cấm.","detail":"Lão giả bản địa tiết lộ nơi này sau khi Thạch Hạo hỏi về các Siêu Tuyệt phong cấp cao hơn. Mức nguy hiểm của địa điểm khiến ông phải hỏi lại liệu Thạch Hạo có thực sự muốn xông vào hay không.","theLucLienQuan":[],"nguon":["@c1273"]},{"id":"nhom-than-phong-tam-muoi-van-nam","name":"Nhóm thần phong tám mươi vạn năm","cn":"","capDo":"khac","parentId":"bac-hai-bai-da","blurb":"Hơn mười ngọn thần phong cao hàng vạn trượng tại Bắc Hải bãi đá. Mỗi ngọn đều gắn với quãng thời gian khoảng tám mươi vạn năm hiếm người chinh phục.","detail":"Lam Tiên từng đăng thành công một ngọn trong nhóm thần phong này. Thạch Hạo đi qua và không dừng lại thử sức vì muốn tiến thẳng tới nơi thí luyện cuối cùng.","theLucLienQuan":[],"nguon":["@c1274"]},{"id":"sau-co-son-tram-van-nam","name":"Sáu cổ sơn trăm vạn năm","cn":"","capDo":"khac","parentId":"bac-hai-bai-da","blurb":"Sáu cổ sơn khổng lồ vây quanh nơi thí luyện cuối cùng. Ngay cả ngọn có kỷ lục thấp nhất cũng đã khoảng trăm vạn năm không người đăng lâm.","detail":"Trên các cổ sơn từng xuất hiện thi thể còn nhiệt độ, quan tài trống, lân vũ và da cũ, làm nảy sinh suy đoán về sinh linh mượn cái chết để thành tiên. Khi Thạch Hạo phá trường vực và tiến vào đường mòn, cả sáu ngọn núi đồng loạt rung chuyển như có sinh mệnh sắp thức tỉnh.","theLucLienQuan":[],"nguon":["@c1274"]},{"id":"duong-mon-giua-sau-co-son","name":"Đường mòn giữa sáu cổ sơn","cn":"","capDo":"khac","parentId":"sau-co-son-tram-van-nam","blurb":"Con đường nhỏ uốn quanh sáu cổ sơn và dẫn vào nơi thí luyện cuối cùng. Lối đi bị trường vực vô hình cùng uy áp có thể xé rách thân thể ngăn cản.","detail":"Người địa phương cảnh báo kẻ thất bại trên đường mòn có thể không bao giờ trở ra. Thạch Hạo dùng một quyền phá trường vực chắn lối rồi mở cửa trong cơ thể để chống lại uy áp khi tiến sâu hơn.","theLucLienQuan":[],"nguon":["@c1274"]},{"id":"duong-mon-duoi-nui","name":"Đường mòn dưới núi","cn":"","capDo":"khac","parentId":"sieu-tuyet-phong","blurb":"Con đường đá gồ ghề dưới Siêu Tuyệt Phong, nơi người đi phải chịu áp lực cực lớn.","detail":"Áp lực trên đường vốn được chuẩn bị cho nhân vật vô địch đạt tới trạng thái cực điểm của một cảnh giới. Thạch Hạo và Thiên Giác Nghĩ nhỏ đều chịu được sức ép để tiến tới cuối đường.","theLucLienQuan":[],"nguon":["@c1275"]},{"id":"son-dao-dan-vao-noi-thi-luyen","name":"Sơn đạo dẫn vào nơi tập luyện","cn":"","capDo":"khac","parentId":"noi-thi-luyen-chung-cuc","blurb":"Đoạn đường cuối dẫn vào khu vực trung tâm của nơi thí luyện chung cực. Người đi qua phải đối mặt với xích thần trật tự, di vật chí cường và sinh linh cầm tàn khí Tiên Đạo.","detail":"Sơn đạo đi giữa các núi lớn và vách núi treo quan tài cổ, đồng thời cấm phi hành. Thạch Hạo vượt qua nhiều tầng tập kích tại đây trước khi khuất khỏi tầm nhìn của đám đông và tiến vào khu vực sâu nhất.","theLucLienQuan":[],"nguon":["@c1276"]},{"id":"chien-truong-trong-noi-thi-luyen-chung-cuc","name":"Chiến trường trong nơi thí luyện chung cực","cn":"","capDo":"khac","parentId":"noi-thi-luyen-chung-cuc","blurb":"Vùng đất hoang vu phủ hắc vụ nằm sâu trong nơi thí luyện chung cực. Chiến trường chất đầy thi thể khổng lồ, binh khí gãy và những dòng máu vẫn còn nóng.","detail":"Không gian rộng lớn có đại địa đỏ đậm và máu chảy thành sông. Nhiều sinh linh mạnh mẽ chết tại đây, thi thể cùng máu vẫn giữ nhiệt độ khiến Thạch Hạo cảm thấy cuộc đại chiến dường như vừa mới kết thúc.","theLucLienQuan":[],"nguon":["@c1276"]},{"id":"chien-truong-day-thi-hai","name":"Chiến trường đầy thi hài","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường rộng lớn gần như không thấy điểm cuối, phủ kín thi thể và những vùng máu tụ của vô số chủng tộc mạnh mẽ.","detail":"Khắp chiến trường là thi thể của nhiều sinh linh mạnh mẽ cùng máu tụ thành sông hồ. Phần lớn máu đã mất tinh hoa, sát khí, linh tính và thần tính, nhưng ở khu vực sâu hơn vẫn có những cột tinh lực giao hòa thành trường vực không thể vượt qua. Nguồn gốc của chiến trường và lý do ngoại giới không biết đến đại chiến này chưa được hé lộ.","theLucLienQuan":[],"nguon":["@c1277"]},{"id":"vuc-ngoai-phia-tren-chien-truong","name":"Vực ngoại phía trên chiến trường","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực vực ngoại nằm phía trên chiến trường, bị những chùm tinh lực từ thi hài xuyên tới.","detail":"Các luồng tinh lực của những cường giả chết trận giao hòa thành chùm sáng, xé rách khu vực vực ngoại phía trên chiến trường và đánh rơi một số ngôi sao.","theLucLienQuan":[],"nguon":["@c1277"]},{"id":"ngon-nui-kim-quang","name":"Ngọn núi kim quang","cn":"","capDo":"khac","parentId":"chien-truong-trong-noi-thi-luyen-chung-cuc","blurb":"Ngọn núi nằm trên đường tới chung cực địa, tỏa kim hà và vang tiếng kinh văn.","detail":"Phía trên ngọn núi có vài tờ da thú màu vàng lơ lửng giữa ánh sáng. Thạch Hạo nghi ngờ kinh văn tại đây chính là Bất Diệt Kinh mà hắn đang tìm kiếm.","theLucLienQuan":[],"nguon":["@c1278"]},{"id":"chien-truong-chi-cuong-gia","name":"Chiến trường Chí Cường giả","cn":"","capDo":"khac","parentId":"noi-thi-luyen-chung-cuc","blurb":"Chiến trường nơi Thiên Giác Nghĩ và Huyết Hoàng Sư quyết chiến.","detail":"Quyền lực của hai hung chủng làm trời đất nứt vỡ, hất tung những thi thể khổng lồ trên mặt đất và khiến hỗn độn khí trào ra từ các khe hư không.","theLucLienQuan":[],"nguon":["@c1279"]},{"id":"day-nui-than-thanh","name":"Dãy núi thần thánh","cn":"","capDo":"vuc","parentId":"noi-thi-luyen-chung-cuc","blurb":"Khu vực núi non nơi trang giấy da thú màu vàng phát hào quang và ngâm tụng kinh văn.","detail":"Phía trên một ngọn núi trong dãy núi, trang giấy da thú màu vàng không ngừng chuyển động, phát ra vô số phù hiệu và tiếng tụng cổ kinh.","theLucLienQuan":[],"nguon":["@c1279"]},{"id":"ngon-nui-co","name":"Ngọn núi cổ","cn":"","capDo":"khac","parentId":"day-nui-than-thanh","blurb":"Ngọn núi gần nơi một bóng người bí ẩn đột ngột hiện thân để nghe cổ kinh.","detail":"Một sinh linh chưa rõ danh tính xuất hiện gần ngọn núi cổ, đứng lắng nghe kinh văn và dường như cảm ngộ chân nghĩa bất diệt.","theLucLienQuan":[],"nguon":["@c1279"]},{"id":"than-thanh-son-mach","name":"Thần thánh sơn mạch","cn":"","capDo":"vuc","parentId":"noi-thi-luyen-chung-cuc","blurb":"Sơn mạch chứa nhiều dấu tích và sinh linh nguy hiểm, đồng thời là khu vực diễn ra cuộc tranh đoạt Bất Diệt Kinh.","detail":"Khu vực có thi hài Chí Cường giả, Luyện Tiên Hồ, Huyết Hoàng Sư và Thần sơn. Hạc Vô Song xuất hiện tại đây để tìm hiểu trang giấy da thú màu vàng, khiến Thạch Hạo xem người này là đối thủ tiềm tàng trong cuộc tranh đoạt Bất Diệt Kinh.","theLucLienQuan":[],"nguon":["@c1280"]},{"id":"than-son","name":"Thần sơn","cn":"","capDo":"khac","parentId":"than-thanh-son-mach","blurb":"Ngọn núi nơi trang giấy da thú màu vàng diễn hóa phù hiệu và Hạc Vô Song tìm hiểu kinh văn.","detail":"Hạc Vô Song đứng dưới núi quan sát kinh văn. Huyết Hoàng Sư sau khi thất thế đã chạy tới đây cầu cứu và công khai gọi người này là chủ nhân.","theLucLienQuan":[],"nguon":["@c1280"]},{"id":"hoanh-dai-son-phong","name":"Hoành Đại Sơn phong","cn":"","capDo":"khac","parentId":"noi-thi-luyen-chung-cuc","blurb":"Ngọn núi lớn đặt những trang da thú màu vàng mang Bất Diệt Kinh.","detail":"Hạc Vô Song nhìn về các trang da thú trên Hoành Đại Sơn phong khi hỏi Thạch Hạo có phải tới tranh đoạt Bất Diệt Kinh hay không.","theLucLienQuan":[],"nguon":["@c1282"]},{"id":"day-nui-chien-truong-chi-cuong-gia","name":"Dãy núi chiến trường Chí Cường giả","cn":"","capDo":"vuc","parentId":"chien-truong-chi-cuong-gia","blurb":"Dãy núi với nhiều cự phong xuyên mây, nơi Thạch Hạo và Hạc Vô Song mở màn cuộc chiến tuyệt đỉnh.","detail":"Địa thế nơi đây vốn kiên cố nhưng bị tràng vực tinh khí thần và cuộc giao chiến giữa Thạch Hạo với Hạc Vô Song phá hủy trên diện rộng. Đá núi nổ nát, không gian sụp đổ và điện hồ phát sinh ngay từ lúc hai người còn chưa trực tiếp ra tay.","theLucLienQuan":["Dị vực"],"nguon":["@c1283"]},{"id":"chien-truong-trong-thoi-khong-thac-loan","name":"Chiến trường trong thời không thác loạn","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường nơi Thạch Hạo và Hạc Vô Song đại diện hai giới quyết chiến trong thời không thác loạn.","detail":"Cuộc va chạm khiến trời đất nứt vỡ và mưa máu thiên khóc trút xuống. Anh linh tiên dân của kỷ nguyên trước hiện hình tại đây, còn Huyết Hoàng Sư suy đoán cuộc gặp giữa hai hạt giống nòng cốt đã tác động tới một sự vật vô hình.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực"],"nguon":["@c1284"]},{"id":"son-ha-tan-pha-cua-ky-nguyen-truoc","name":"Sơn hà tàn phá của kỷ nguyên trước","cn":"","capDo":"khac","parentId":"chien-truong-trong-thoi-khong-thac-loan","blurb":"Bóng sơn hà mang đạo vận và nỗi đau mất đất của những tiên dân chết trận trong kỷ nguyên trước.","detail":"Sơn hà tàn phá hiện lên quanh Thạch Hạo cùng những khuôn mặt đẫm huyết lệ của tiên dân. Đạo vận và ý niệm bất khuất tại đây cộng hưởng với hắn trước khi bị lực lượng dị vực áp chế và đánh tan.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực"],"nguon":["@c1284"]},{"id":"hon-don-cung-dien","name":"Hỗn Độn cung điện","cn":"","aliases":[],"capDo":"khac","parentId":"khe-nut-hu-khong-chien-truong","blurb":"Cung điện hùng vĩ được Hỗn Độn khí bao phủ, xuất hiện sâu trong khe nứt hư không.","detail":"Cửa cung điện mở rộng, bên trong có những vật đáng sợ đang đối đầu và có nguy cơ phát sinh va chạm tuyệt thế. Mức nguy hiểm của nơi này được mô tả còn vượt nhuốm máu hắc sắc cổ thuyền.","theLucLienQuan":[],"nguon":["@c1285"]},{"id":"khe-nut-hu-khong-chien-truong","name":"Khe nứt hư không chiến trường","cn":"","aliases":[],"capDo":"khac","parentId":"chien-truong-trong-thoi-khong-thac-loan","blurb":"Hệ thống khe nứt lớn hình thành khi đòn quyết chiến của Thạch Hạo và Hạc Vô Song phá nát chiến trường.","detail":"Một sức mạnh thần bí chống đỡ khiến các khe nứt không thể tự khép lại. Tàn thể của Thạch Hạo và Hạc Vô Song rơi vào những khu vực khác nhau, còn Hỗn Độn cung điện xuất hiện tại nơi sâu nhất.","theLucLienQuan":["Dị Vực"],"nguon":["@c1285"]},{"id":"khe-nut-hu-khong-lon","name":"Khe nứt hư không lớn","cn":"","capDo":"khac","parentId":"chien-truong-trong-thoi-khong-thac-loan","blurb":"Khu vực không gian bất ổn chứa máu, xương vỡ và những mảnh pháp khí sau trận chiến.","detail":"Thiên Giác Nghĩ và Huyết Hoàng Sư tìm kiếm giữa các khe nứt này. Đầu lâu của Hạc Vô Song và Thạch Hạo lần lượt được phát hiện tại đây.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1286"]},{"id":"ngon-nui-dat-bat-diet-kinh","name":"Ngọn núi đặt Bất Diệt Kinh","cn":"","capDo":"khac","parentId":"chien-truong-trong-thoi-khong-thac-loan","blurb":"Cự sơn có cấm chế và ánh sáng màu vàng, trên đỉnh đặt trang da thú chứa Bất Diệt Kinh.","detail":"Hạc Vô Song và Thạch Hạo cùng vượt qua ánh sáng cấm chế, áp sát đỉnh núi rồi vừa tranh trang da thú vừa công kích lẫn nhau.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1286"]},{"id":"chien-truong-co-tren-day-nui-than-thanh","name":"Chiến trường cổ trên dãy núi thần thánh","cn":"","capDo":"khac","parentId":"day-nui-than-thanh","blurb":"Chiến trường nơi Thạch Hạo và Hạc Vô Song quyết chiến vì Bất Diệt Kinh.","detail":"Sau quãng thời gian dài như một kỷ nguyên, nơi đây mất hết dấu vết thần thánh; máu, thi thể cường giả và những trang Bất Diệt Kinh đều biến mất, còn cây cổ thụ phủ lên xương khô.","theLucLienQuan":["Dị vực"],"nguon":["@c1287"]},{"id":"co-chien-truong-tien-co","name":"Cổ chiến trường Tiên cổ","cn":"","capDo":"khac","parentId":"noi-thi-luyen-chung-cuc","blurb":"Chiến trường hoang vu từng chôn vùi nhiều cường giả, Chân Tiên và Trường Sinh giả. Máu cổ vẫn nhuộm đỏ sậm núi non, còn tâm tình bất diệt của người chết trận hóa thành anh linh.","detail":"Đây là diện mạo hiện tại của chung cực nơi tập luyện. Cảnh biển thi thể và máu trong thử luyện phản ánh hình dạng chiến trường sau khi vùng đất này rơi vào tay Dị vực.","theLucLienQuan":["Dị vực"],"nguon":["@c1288"]},{"id":"bat-diet-phong","name":"Bất Diệt phong","cn":"","capDo":"khac","parentId":"noi-thi-luyen-chung-cuc","blurb":"Ngọn núi lưu giữ bốn trang đầu Bất Diệt Kinh và có khả năng ảnh hưởng cân bằng thời gian. Dù từng bị các Bất Hủ Dị vực đánh gãy, nó vẫn tự khôi phục và khiến kinh văn tái hiện.","detail":"Bất Diệt Kinh được khắc trên ngọn núi này, còn các trang da thú màu vàng chỉ là phù văn ngưng tụ. Người vượt qua thử thách và có Kinh thược có thể tiếp cận truyền thừa.","theLucLienQuan":["Dị vực","Thiên Giác Nghĩ bộ tộc"],"nguon":["@c1289"]},{"id":"vung-cam-chua-nam-trang-bat-diet-kinh","name":"Vùng cấm chứa năm trang Bất Diệt Kinh","cn":"","capDo":"vuc","parentId":"cuu-thien-thap-dia","blurb":"Một trong những vùng cấm đáng sợ nhất Cửu Thiên Thập Địa, được truyền là nơi lưu giữ năm trang cuối của Bất Diệt Kinh.","detail":"Chỉ rất ít người biết vị trí vùng cấm này. Muốn hoàn thành toàn bộ chín trang Bất Diệt Kinh, người tu luyện phải tìm được phần truyền thừa được cho là cất giữ tại đây.","theLucLienQuan":[],"nguon":["@c1289"]},{"id":"bat-tu-noi","name":"Bất tử nơi","cn":"","capDo":"vuc","parentId":null,"blurb":"Một vùng cấm vĩ đại và đáng sợ, nơi cất giữ năm trang bản hạ của Bất Diệt Kinh.","detail":"Bất tử nơi nguy hiểm đến mức ngay cả người thuộc các thế gia trường sinh cũng tránh tới gần. Muốn hoàn thành cả thượng và hạ thiên Bất Diệt Kinh, người tu phải tiến vào vùng cấm này để tìm năm trang còn lại.","theLucLienQuan":[],"nguon":["@c1290","@c1291"]},{"id":"chung-cuc-noi-tap-luyen","name":"Chung cực nơi tập luyện","cn":"","capDo":"khac","parentId":"bac-hai","blurb":"Tử địa mà suốt kỷ nguyên hiện tại chưa từng có người tiến vào rồi sống sót trở ra.","detail":"Thạch Hạo sống sót rời khỏi nơi này, phá vỡ thần thoại tử vong tuyệt đối và gây chấn động khắp các cự thành Bắc Hải.","theLucLienQuan":[],"nguon":["@c1291"]},{"id":"co-dia-mai-tang-tien-dan","name":"Cổ địa mai táng tiên dân","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Cổ địa chôn hài cốt của những tiên dân và chiến giả đã chết trong cuộc tàn sát thời Tiên cổ.","detail":"Lòng đất trấn áp sát khí hình thành từ các anh linh chết trận. Vào thời điểm đặc biệt, sát khí có thể bùng phát dữ dội đến mức Chí Tôn cũng phải biến sắc.","theLucLienQuan":["Dị vực"],"nguon":["@c1291"]},{"id":"vuc-ngoai-bac-hai","name":"Vực ngoại Bắc Hải","cn":"","capDo":"vuc","parentId":"vuc-ngoai","blurb":"Vùng ngoài Bắc Hải, nơi Vương gia bố trí sát cục nhắm vào Thạch Hạo.","detail":"Thạch Hạo bị cương phong cuốn khỏi Bắc Hải tới đây rồi đối mặt Vương Mãng Long cùng một lão giả Vương gia. Cuồng phong, mưa lớn và khói đen được dùng để che mắt người ngoài về vụ phục kích.","theLucLienQuan":["Vương gia"],"nguon":["@c1291"]},{"id":"truong-sinh-vuong-phu","name":"Trường Sinh vương phủ","cn":"","capDo":"khac","parentId":"vo-luong-thien","blurb":"Một trong ba động phủ nổi danh nhất Vô Lượng Thiên và là địa bàn trọng yếu của Vương gia.","detail":"Nơi này từng sinh ra Trường Sinh giả từ thời Tiên cổ. Địa thế gồm những dãy núi mang hình long xà, Kỳ Lân và Phượng Hoàng, cổ mộc che trời, thụy khí cùng sương trắng bao phủ.","theLucLienQuan":["Vương gia"],"nguon":["@c1294"]},{"id":"vung-nui-song-tam-tram-dam-truoc-vuong-gia","name":"Vùng núi sông tám trăm dặm trước Vương gia","cn":"","capDo":"vuc","parentId":"truong-sinh-vuong-phu","blurb":"Khu vực ngoại vi nằm trước Trường Sinh vương phủ, thuộc tuyến phòng vệ của Vương gia.","detail":"Khu vực này được bao phủ bởi tuyệt sát đại trận có thể uy hiếp Chí Cường giả. Đại Trưởng Lão mang Thạch Hạo cưỡng ép vượt qua, khiến lôi đình bùng phát, mặt đất nứt vỡ và dung nham trào lên.","theLucLienQuan":["Vương gia"],"nguon":["@c1294"]},{"id":"son-mon-vuong-gia","name":"Sơn môn Vương gia","cn":"","capDo":"khac","parentId":"tien-gia-tinh-tho-vuong-gia","blurb":"Cửa ngõ dẫn vào tịnh thổ của Vương gia, gồm cổng chào cảnh giới bên ngoài và Ngôi sao điện trấn giữ đường vào phía trong.","detail":"Cổng chào của sơn môn bị phá sập khi Mạnh Thiên Chính dẫn Thạch Hạo xông vào. Ngôi sao điện bảo vệ con đường duy nhất dẫn tới tịnh thổ sau đó cũng bị phá hủy.","theLucLienQuan":["Vương gia"],"nguon":["@c1295"]},{"id":"tien-gia-tinh-tho-vuong-gia","name":"Tiên gia tịnh thổ Vương gia","cn":"","capDo":"khac","parentId":null,"blurb":"Đạo trường rộng lớn của Vương gia, có hơn vạn ngọn thần sơn và cảnh tượng tiên gia.","detail":"Tịnh thổ có linh khí, tiên vụ, thác bạc, đảo nổi, thụy cầm và tường thú. Nơi này từng sinh ra trường sinh giả vào thời Tiên Cổ và vẫn được Vương gia bảo tồn.","theLucLienQuan":["Vương gia"],"nguon":["@c1295"]},{"id":"ngoi-sao-dien","name":"Ngôi sao điện","cn":"","capDo":"khac","parentId":"son-mon-vuong-gia","blurb":"Điện phủ màu trắng bạc trấn giữ con đường duy nhất dẫn vào tịnh thổ Vương gia.","detail":"Công trình khổng lồ được đúc từ kim loại và đóng vai trò cửa ngõ của Vương gia. Mạnh Thiên Chính ném đầu cửu thế tổ vào điện, khiến toàn bộ cung điện nổ thành vô số mảnh kim loại.","theLucLienQuan":["Vương gia"],"nguon":["@c1295"]},{"id":"dai-ban-doanh-vuong-gia","name":"Vương gia","cn":"","capDo":"khac","parentId":null,"blurb":"Đại bản doanh của Trường Sinh thế gia Vương gia, nơi chín người con của Vương Trường Sinh được xem là nội tình gia tộc.","detail":"Mạnh Thiên Chính dẫn Thạch Hạo và Kim đến đây đòi lời giải thích. Ông giao chiến với Vương Đại ở khu vực này, sau đó được Vương Trường Sinh mời tiến sâu vào bên trong.","theLucLienQuan":["Vương gia"],"nguon":["@c1296"]},{"id":"co-dia-vuong-gia","name":"Cổ địa Vương gia","cn":"","capDo":"gioi-nho","parentId":"tien-gia-tinh-tho-vuong-gia","blurb":"Không gian cổ xưa nằm bên trong phủ đệ Vương gia, rộng lớn như một thế giới nguyên thủy từ thời Tiên cổ. Nơi đây có hơn vạn linh sơn, đại trận bất hoại và nhiều Thái cổ hung vật bảo vệ.","detail":"Cổ địa Vương gia gồm hơn vạn linh sơn, các đồng điện, nhà đá và bia kim loại khắc Bất Hủ đạo văn. Nhiều Hắc Hống, Kim Ô và Thái cổ cự hung bị nuôi dưỡng hoặc hàng phục tại đây, khiến toàn bộ khu vực trở thành hiểm địa khó bị ngoại giới công phá.","theLucLienQuan":["Vương gia"],"nguon":["@c1297","@c1299"]},{"id":"to-dien-vuong-gia","name":"Tổ điện Vương gia","cn":"","capDo":"khac","parentId":"co-dia-vuong-gia","blurb":"Cổ điện bằng đá do thủy tổ Chân Tiên của Vương gia tự xây trước khi thành tiên. Đây là nơi chín người con tụ hội và Vương Trường Sinh chính thức xuất hiện.","detail":"Tổ điện nằm ở điểm cuối hành trình xuyên qua cổ địa Vương gia, được hàng nghìn con rồng do hỗn độn khí hóa thành bao quanh. Mạnh Thiên Chính dung hợp chân thân với linh thân trước điện, còn Vương Trường Sinh từ bên trong bước ra với hình dáng thiếu niên.","theLucLienQuan":["Vương gia"],"nguon":["@c1297","@c1299"]}]};
